    int? videoVersion,
    double? videoCropScale,
    double? videoCropOffsetX,
    double? videoCropOffsetY,
    String? videoThumbnailBytesBase64,
  }) =>
      UserProfile(
        name: name ?? this.name,
        photoPath: clearPhoto ? null : (photoPath ?? this.photoPath),
        photoBytesBase64: clearPhoto ? null : (photoBytesBase64 ?? this.photoBytesBase64),
        photoVersion: photoVersion ?? this.photoVersion,
        videoPath: clearVideo ? null : (videoPath ?? this.videoPath),
        videoVersion: videoVersion ?? this.videoVersion,
        videoCropScale: clearVideo ? 1.0 : (videoCropScale ?? this.videoCropScale),
        videoCropOffsetX: clearVideo ? 0.0 : (videoCropOffsetX ?? this.videoCropOffsetX),
        videoCropOffsetY: clearVideo ? 0.0 : (videoCropOffsetY ?? this.videoCropOffsetY),
        videoThumbnailBytesBase64: clearVideo ? null : (videoThumbnailBytesBase64 ?? this.videoThumbnailBytesBase64),
      );

  Map<String, dynamic> toJson() => {
        'name': name,
        'photoPath': photoPath,
        'photoBytesBase64': photoBytesBase64,
        'photoVersion': photoVersion,
        'videoPath': videoPath,
        'videoVersion': videoVersion,
        'videoCropScale': videoCropScale,
        'videoCropOffsetX': videoCropOffsetX,
        'videoCropOffsetY': videoCropOffsetY,
        'videoThumbnailBytesBase64': videoThumbnailBytesBase64,
      };
  factory UserProfile.fromJson(Map<String, dynamic> json) => UserProfile(
        name: json['name'] as String? ?? '',
        photoPath: json['photoPath'] as String?,
        photoBytesBase64: json['photoBytesBase64'] as String?,
        photoVersion: json['photoVersion'] as int? ?? 0,
        videoPath: json['videoPath'] as String?,
        videoVersion: json['videoVersion'] as int? ?? 0,
        videoCropScale: (json['videoCropScale'] as num?)?.toDouble() ?? 1.0,
        videoCropOffsetX: (json['videoCropOffsetX'] as num?)?.toDouble() ?? 0.0,
        videoCropOffsetY: (json['videoCropOffsetY'] as num?)?.toDouble() ?? 0.0,
        videoThumbnailBytesBase64: json['videoThumbnailBytesBase64'] as String?,
      );
}

final userProfileProvider = StateNotifierProvider<UserProfileNotifier, UserProfile>(
  (ref) => UserProfileNotifier(ref.watch(prefsProvider)),
);

class UserProfileNotifier extends StateNotifier<UserProfile> {
  final SharedPreferences prefs;
  static const _key = 'user_profile';

  UserProfileNotifier(this.prefs) : super(_load(prefs));

  static UserProfile _load(SharedPreferences prefs) {
    final raw = prefs.getString(_key);
    if (raw == null || raw.isEmpty) return const UserProfile();
    try {
      return UserProfile.fromJson(jsonDecode(raw) as Map<String, dynamic>);
    } catch (_) {
      return const UserProfile();
    }
  }

  void _persist() {
    prefs.setString(_key, jsonEncode(state.toJson()));
  }

  void updateName(String name) {
    final trimmed = name.trim();
    if (trimmed.isEmpty) return;
    state = state.copyWith(name: trimmed);
    _persist();
  }

  Future<void> updatePhoto({String? path, Uint8List? bytes}) async {
    // Foto dan video profil bersifat saling menggantikan: hanya salah satu
    // yang boleh aktif dalam satu waktu. Saat pengguna mengatur foto baru,
    // video profil yang sedang aktif (jika ada) otomatis dihapus beserta
    // berkasnya di disk agar tidak menyisakan data yatim.
    final oldVideoPath = state.videoPath;
    if (!kIsWeb && oldVideoPath != null) {
      final oldVideoFile = File(oldVideoPath);
      if (await oldVideoFile.exists()) {
        try {
          await oldVideoFile.delete();
        } catch (_) {}
      }
    }
    if (!kIsWeb && path != null) {
      final oldPath = state.photoPath;
      if (oldPath != null && oldPath != path) {
        PaintingBinding.instance.imageCache.evict(FileImage(File(oldPath)));
      }
      state = state.copyWith(
        photoPath: path,
        photoVersion: state.photoVersion + 1,
        clearVideo: true,
        videoVersion: state.videoVersion + 1,
      );
    } else if (kIsWeb && bytes != null) {
      state = state.copyWith(
        photoBytesBase64: base64Encode(bytes),
        photoVersion: state.photoVersion + 1,
        clearVideo: true,
        videoVersion: state.videoVersion + 1,
      );
    } else {
      return;
    }
    _persist();
  }

  Future<void> removePhoto() async {
    final oldPath = state.photoPath;
    if (!kIsWeb && oldPath != null) {
      PaintingBinding.instance.imageCache.evict(FileImage(File(oldPath)));
      final file = File(oldPath);
      if (await file.exists()) {
        try {
          await file.delete();
        } catch (_) {}
      }
    }
    state = state.copyWith(clearPhoto: true, photoVersion: state.photoVersion + 1);
    _persist();
  }

  Future<void> updateVideo({required String path, required double scale, required double offsetX, required double offsetY, String? thumbnailBytesBase64}) async {
    // Foto dan video profil bersifat saling menggantikan: hanya salah satu
    // yang boleh aktif dalam satu waktu. Saat pengguna mengatur video baru,
    // foto profil yang sedang aktif (jika ada) otomatis dihapus beserta
    // berkasnya di disk agar tidak menyisakan data yatim.
    final oldPhotoPath = state.photoPath;
    if (!kIsWeb && oldPhotoPath != null) {
      PaintingBinding.instance.imageCache.evict(FileImage(File(oldPhotoPath)));
      final oldPhotoFile = File(oldPhotoPath);
      if (await oldPhotoFile.exists()) {
        try {
          await oldPhotoFile.delete();
        } catch (_) {}
      }
    }
    state = state.copyWith(
      videoPath: path,
      videoVersion: state.videoVersion + 1,
      videoCropScale: scale,
      videoCropOffsetX: offsetX,
      videoCropOffsetY: offsetY,
      videoThumbnailBytesBase64: thumbnailBytesBase64,
      clearPhoto: true,
      photoVersion: state.photoVersion + 1,
    );
    _persist();
  }

  Future<void> removeVideo() async {
    final oldPath = state.videoPath;
    if (oldPath != null) {
      final file = File(oldPath);
      if (await file.exists()) {
        try {
          await file.delete();
        } catch (_) {}
      }
    }
    state = state.copyWith(clearVideo: true, videoVersion: state.videoVersion + 1);
    _persist();
  }
}

class ProfilePhotoPick {
  final String? path;
  final Uint8List? bytes;
