class _VideoCropPageState extends State<_VideoCropPage> {
  static const double _previewSize = 280;
  VideoPlayerController? _controller;
  double _scale = 1.0;
  double _baseScale = 1.0;
  Offset _offset = Offset.zero;
  Offset _baseOffset = Offset.zero;
  Offset _startFocalPoint = Offset.zero;

  @override
  void initState() {
    super.initState();
    _appendDartCrashLog('[Checkpoint ${DateTime.now()}] VideoCrop: page reached, path=${widget.videoPath}');
    _setup();
  }

  Future<void> _setup() async {
    final controller = VideoPlayerController.file(
      File(widget.videoPath),
      videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
    );
    try {
      await controller.initialize();
      await controller.setLooping(true);
      await controller.setVolume(0);
    } catch (_) {
      controller.dispose();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Video tidak didukung di perangkat ini, coba video lain.')),
        );
        Navigator.pop(context);
      }
      return;
    }
    if (!mounted) {
      controller.dispose();
      return;
    }
    setState(() => _controller = controller);
    controller.play();
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  void _onScaleStart(ScaleStartDetails details) {
    _baseScale = _scale;
    _baseOffset = _offset;
    _startFocalPoint = details.focalPoint;
  }

  void _onScaleUpdate(ScaleUpdateDetails details) {
    setState(() {
      _scale = (_baseScale * details.scale).clamp(1.0, 4.0);
      _offset = _baseOffset + (details.focalPoint - _startFocalPoint);
    });
  }

  void _save() {
    Navigator.pop(
      context,
      _VideoCropResult(
        scale: _scale,
        offsetX: _offset.dx / _previewSize,
        offsetY: _offset.dy / _previewSize,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        backgroundColor: Colors.black,
        elevation: 0,
        iconTheme: const IconThemeData(color: Colors.white),
        title: const Text('Atur Posisi', style: TextStyle(color: Colors.white, fontSize: 16)),
        actions: [
          TextButton(
            onPressed: controller == null ? null : _save,
            child: const Text('Simpan', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
          ),
        ],
      ),
      body: SafeArea(
        child: Center(
          child: controller == null
              ? const CircularProgressIndicator(color: Colors.white)
              : GestureDetector(
                  onScaleStart: _onScaleStart,
                  onScaleUpdate: _onScaleUpdate,
                  child: SizedBox(
                    width: _previewSize,
                    height: _previewSize,
                    child: Stack(
                      children: [
                        Positioned.fill(
                          child: ClipRect(
                            child: Transform.translate(
                              offset: _offset,
                              child: Transform.scale(
                                scale: _scale,
                                child: FittedBox(
                                  fit: BoxFit.cover,
                                  child: SizedBox(
                                    width: controller.value.size.width,
                                    height: controller.value.size.height,
                                    child: VideoPlayer(controller),
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ),
                        Positioned.fill(
                          child: IgnorePointer(
                            child: CustomPaint(
                              painter: _VideoCircleCutoutPainter(overlayColor: Colors.black.withOpacity(0.55)),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
        ),
      ),
    );
  }
}

Future<void> pickAndSetProfileVideo(BuildContext context, WidgetRef ref, ImageSource source) async {
  final picker = ImagePicker();
  final XFile? picked = await picker.pickVideo(source: source, maxDuration: const Duration(seconds: 60));
  if (picked == null || !context.mounted) return;

  final trimmedPath = await Navigator.push<String>(
    context,
    GlassPageRoute(builder: (_) => _VideoTrimPage(sourcePath: picked.path)),
  );
  if (trimmedPath == null || !context.mounted) return;

  final cropResult = await Navigator.push<_VideoCropResult>(
    context,
    GlassPageRoute(builder: (_) => _VideoCropPage(videoPath: trimmedPath)),
  );
  if (cropResult == null) return;

  final dir = await getApplicationDocumentsDirectory();
  final destPath = '${dir.path}/profile_video.mp4';
  final destFile = File(destPath);
  if (await destFile.exists()) {
    try {
      await destFile.delete();
    } catch (_) {}
  }
  await File(trimmedPath).copy(destPath);
  try {
    await File(trimmedPath).delete();
  } catch (_) {}

  final thumbnailBase64 = await _extractVideoThumbnailBase64(destPath);

  ref.read(userProfileProvider.notifier).updateVideo(
        path: destPath,
        scale: cropResult.scale,
        offsetX: cropResult.offsetX,
        offsetY: cropResult.offsetY,
        thumbnailBytesBase64: thumbnailBase64,
      );
}

class _GalleryMediaPick {
  final bool isVideo;
  final String? path;
  final Uint8List? bytes;
  const _GalleryMediaPick({required this.isVideo, this.path, this.bytes});
}

const _videoFileExtensions = ['.mp4', '.mov', '.avi', '.mkv', '.webm', '.3gp', '.m4v', '.wmv', '.flv'];

bool _looksLikeVideoPath(String path) {
  final lower = path.toLowerCase();
  return _videoFileExtensions.any((ext) => lower.endsWith(ext));
}

// Unified gallery picker: opens the same native "real gallery app" chooser
// used for images, but now accepts both photos and videos in one dialog.
Future<_GalleryMediaPick?> _pickMediaFromGallery() async {
  if (!kIsWeb && Platform.isAndroid) {
    final String? pickedPath = await _galleryChooserChannel.invokeMethod<String>('pickMediaWithChooser');
    if (pickedPath == null) return null;
    return _GalleryMediaPick(isVideo: _looksLikeVideoPath(pickedPath), path: pickedPath);
  }

  final picker = ImagePicker();
  final XFile? picked = await picker.pickMedia();
  if (picked == null) return null;
  final isVideo = _looksLikeVideoPath(picked.path);

  if (kIsWeb) {
    final bytes = await picked.readAsBytes();
    return _GalleryMediaPick(isVideo: isVideo, bytes: bytes);
  }
  return _GalleryMediaPick(isVideo: isVideo, path: picked.path);
}

// Called from the "Choose from gallery" menu item: lets the user pick either
// a photo or a video from the gallery, then routes to the matching
// crop (photo) or trim+crop (video) flow.
Future<void> pickAndSetProfileMediaFromGallery(BuildContext context, WidgetRef ref) async {
  final pick = await _pickMediaFromGallery();
  if (pick == null || !context.mounted) return;

  // Berkas asli yang disalin native chooser ke cacheDir (picked_profile_media_*)
  // HARUS selalu dibersihkan di akhir alur ini, apa pun hasilnya (lanjut atau
  // dibatalkan pengguna di tengah crop/trim). Sebelumnya berkas ini tidak
  // pernah dihapus sama sekali, sehingga setiap kali memilih foto/video dari
  // galeri menyisakan salinan penuh berkas asli di cache — lama-lama
  // menumpuk sampai ratusan MB.
  Future<void> cleanupSource() async {
    final sourcePath = pick.path;
    if (kIsWeb || sourcePath == null) return;
    try {
      final f = File(sourcePath);
      if (await f.exists()) await f.delete();
    } catch (_) {}
  }

  if (pick.isVideo) {
    final sourcePath = pick.path;
    if (sourcePath == null) {
      await cleanupSource();
      return;
    }

    final trimmedPath = await Navigator.push<String>(
      context,
      GlassPageRoute(builder: (_) => _VideoTrimPage(sourcePath: sourcePath)),
    );
    if (trimmedPath == null || !context.mounted) {
      await cleanupSource();
      return;
    }

    final cropResult = await Navigator.push<_VideoCropResult>(
      context,
      GlassPageRoute(builder: (_) => _VideoCropPage(videoPath: trimmedPath)),
    );
    if (cropResult == null) {
      try {
        await File(trimmedPath).delete();
      } catch (_) {}
      await cleanupSource();
      return;
    }

    final dir = await getApplicationDocumentsDirectory();
    final destPath = '${dir.path}/profile_video.mp4';
    final destFile = File(destPath);
    if (await destFile.exists()) {
      try {
        await destFile.delete();
      } catch (_) {}
    }
    await File(trimmedPath).copy(destPath);
    try {
      await File(trimmedPath).delete();
    } catch (_) {}
    await cleanupSource();

    final thumbnailBase64 = await _extractVideoThumbnailBase64(destPath);

    ref.read(userProfileProvider.notifier).updateVideo(
          path: destPath,
          scale: cropResult.scale,
          offsetX: cropResult.offsetX,
          offsetY: cropResult.offsetY,
          thumbnailBytesBase64: thumbnailBase64,
        );
  } else {
    Uint8List? rawBytes = pick.bytes;
    if (rawBytes == null && pick.path != null) {
      rawBytes = await File(pick.path!).readAsBytes();
    }
    await cleanupSource();
    if (rawBytes == null || !context.mounted) return;

    final croppedBytes = await Navigator.push<Uint8List>(
      context,
      GlassPageRoute(builder: (_) => _CropperPage(imageBytes: rawBytes!)),
    );
    if (croppedBytes == null) return;

    if (kIsWeb) {
      ref.read(userProfileProvider.notifier).updatePhoto(bytes: croppedBytes);
      return;
    }

    final dir = await getApplicationDocumentsDirectory();
    final destPath = '${dir.path}/profile_photo.jpg';
    final destFile = File(destPath);
    if (await destFile.exists()) {
      try {
        await destFile.delete();
      } catch (_) {}
    }
    await destFile.writeAsBytes(croppedBytes);
    ref.read(userProfileProvider.notifier).updatePhoto(path: destPath);
  }
}

class AppThemePalette {
  final String name;
  final Color primary, secondary, tertiary;
  const AppThemePalette(this.name, this.primary, this.secondary, this.tertiary);
}

const _customPalettes = [
  AppThemePalette('Lavender Glow', Color(0xFF7655D8), Color(0xFFD6F6A6), Color(0xFFF4EDFF)),
  AppThemePalette('Emerald City', Color(0xFF24A148), Color(0xFFD6F6A6), Color(0xFFE7F7EA)),
  AppThemePalette('Rose Petal', Color(0xFFE05270), Color(0xFFFFD8E4), Color(0xFFFBE8ED)),
  AppThemePalette('Ocean Breeze', Color(0xFF2196F3), Color(0xFFFFC107), Color(0xFFE3F2FD)),
  AppThemePalette('Sunset Vibes', Color(0xFFFF9800), Color(0xFF4CAF50), Color(0xFFFFF3E0)),
];

// Menambahkan seluruh skema warna bawaan dari package flex_color_scheme agar
// pilihan warna tema jauh lebih banyak (50+ skema siap pakai) dibanding hanya
// 5 palet custom di atas. Setiap skema sudah dirancang harmonis oleh
// flex_color_scheme (primary/secondary/tertiary saling cocok) sehingga aman
// dipakai langsung sebagai AppThemePalette tanpa perlu diracik manual satu per satu.
final List<AppThemePalette> _flexPalettes = FlexColor.schemesList
    .map((scheme) => AppThemePalette(
          scheme.name,
          scheme.light.primary,
          scheme.light.secondary,
          scheme.light.tertiary ?? scheme.light.secondary,
        ))
    .toList();

final List<AppThemePalette> appPalettes = [..._customPalettes, ..._flexPalettes];

final tabProvider = StateProvider<int>((ref) => 0);
final selectedCardProvider = StateProvider<int>((ref) => -1);
