class AppFormatters {
  static final NumberFormat thousands = NumberFormat('#,###', 'id_ID');
  static final DateFormat hourMinute = DateFormat('hh:mm a');
  static final DateFormat dateTimeFull = DateFormat('d MMM yyyy, hh:mm a');
  static final DateFormat dateOnly = DateFormat('d MMM yyyy');
  static final DateFormat _monthYearId = DateFormat('MMMM yyyy', 'id_ID');
  static final DateFormat _monthYearEn = DateFormat('MMMM yyyy', 'en_US');
  static final DateFormat _dateTimeMinuteId = DateFormat('d MMM yyyy, HH:mm', 'id_ID');
  static final DateFormat _dateTimeMinuteEn = DateFormat('d MMM yyyy, HH:mm', 'en_US');

  static DateFormat monthYear(AppLang lang) => lang == AppLang.id ? _monthYearId : _monthYearEn;
  static DateFormat dateTimeMinute(AppLang lang) => lang == AppLang.id ? _dateTimeMinuteId : _dateTimeMinuteEn;

  static String rupiah(num value) => 'Rp ${thousands.format(value).replaceAll(',', '.')}';
}

class ThousandsInputFormatter extends TextInputFormatter {
  @override
  TextEditingValue formatEditUpdate(TextEditingValue oldValue, TextEditingValue newValue) {
    final digits = newValue.text.replaceAll(RegExp(r'[^0-9]'), '');
    if (digits.isEmpty) {
      return newValue.copyWith(text: '');
    }
    final number = int.parse(digits);
    final formatted = AppFormatters.thousands.format(number).replaceAll(',', '.');
    return TextEditingValue(
      text: formatted,
      selection: TextSelection.collapsed(offset: formatted.length),
    );
  }
}

class GlassPageRoute<T> extends MaterialPageRoute<T> {
  GlassPageRoute({required super.builder});
}

// Route khusus untuk membuka preview media profil (foto/video) secara
// fullscreen. Sengaja TIDAK memakai transisi slide bawaan MaterialPageRoute
// (GlassPageRoute) karena itu akan "bertabrakan" dengan animasi Hero flight
// bertag 'profile-header-media' — dua gerakan berbeda yang berjalan
// bersamaan (halaman slide naik + hero berpindah posisi/ukuran) terlihat
// patah-patah, bukan menyatu. Di sini halaman baru hanya di-fade in/out;
// perpindahan posisi & ukuran media sepenuhnya diserahkan ke Hero flight,
// sehingga transisi dari avatar yang sedang membesar (saat ditarik ke
// bawah) menuju preview penuh terasa satu gerakan yang mulus & seamless.
class MediaPreviewRoute<T> extends PageRouteBuilder<T> {
  final WidgetBuilder builder;
  MediaPreviewRoute({required this.builder})
      : super(
          opaque: false,
          barrierColor: Colors.transparent,
          transitionDuration: const Duration(milliseconds: 380),
          reverseTransitionDuration: const Duration(milliseconds: 300),
          pageBuilder: (context, animation, secondaryAnimation) => builder(context),
          transitionsBuilder: (context, animation, secondaryAnimation, child) {
            final curved = CurvedAnimation(
              parent: animation,
              curve: Curves.easeOutCubic,
              reverseCurve: Curves.easeInCubic,
            );
            return FadeTransition(opacity: curved, child: child);
          },
        );
}

void showGlassSnackBar(BuildContext context, String message, {IconData? icon}) {
  ScaffoldMessenger.of(context).hideCurrentSnackBar();
  ScaffoldMessenger.of(context).showSnackBar(
    SnackBar(
      content: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          if (icon != null) ...[
            Icon(icon, size: 18, color: Colors.white),
            const SizedBox(width: 10),
          ],
          Flexible(child: Text(message)),
        ],
      ),
      behavior: SnackBarBehavior.floating,
      duration: const Duration(milliseconds: 2200),
    ),
  );
}

