          // regangan elastis tipis pada sheet (sheetRubberScale), TIDAK
          // mengubah urutan layer — Sheet tetap selalu di depan Media.
          Transform.scale(
            alignment: Alignment.topCenter,
            scale: sheetRubberScale,
            child: Opacity(
            opacity: sheetOpacity,
