class AnimatedTransactionTile extends ConsumerWidget {
  final FinanceTransaction item;
  final Widget child;
  const AnimatedTransactionTile({super.key, required this.item, required this.child});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final isRemoving = ref.watch(removingTransactionIdsProvider).contains(item.id);
    return AnimatedSize(
      duration: const Duration(milliseconds: 300),
      curve: Curves.easeInOut,
      alignment: Alignment.topCenter,
      child: AnimatedOpacity(
        opacity: isRemoving ? 0.0 : 1.0,
        duration: const Duration(milliseconds: 260),
        curve: Curves.easeOut,
        // PENTING: child TIDAK boleh diganti dengan widget lain (mis. SizedBox kosong)
        // saat isRemoving, karena itu membuat BuildContext dari tile ini ter-unmount
        // sebelum callback penghapusan (Future.delayed) sempat berjalan. Akibatnya
        // context.mounted menjadi false, ref.read(transactionsProvider.notifier).remove()
        // batal dipanggil, transaksi tidak benar-benar terhapus, dan saldo utama tidak
        // ter-update meski item sudah tidak terlihat di daftar.
        child: IgnorePointer(
          ignoring: isRemoving,
          child: ConstrainedBox(
            constraints: isRemoving ? const BoxConstraints(maxHeight: 0) : const BoxConstraints(),
            child: ClipRect(child: child),
          ),
        ),
      ),
    );
  }
}

