}
return ClipOval(
key: ValueKey('avatar-web-$photoVersion'),
child: Image.memory(
bytes,
width: diameter,
height: diameter,
fit: BoxFit.cover,
cacheWidth: cacheDim,
cacheHeight: cacheDim,
gaplessPlayback: true,
errorBuilder: (context, error, stackTrace) => _fallback(primary),
),
);
}

if (photoPath == null) return _fallback(primary);
return ClipOval(
key: ValueKey('avatar-$photoVersion'),
child: Image.file(
File(photoPath!),
width: diameter,
height: diameter,
fit: BoxFit.cover,
cacheWidth: cacheDim,
cacheHeight: cacheDim,
errorBuilder: (context, error, stackTrace) => _fallback(primary),
),
);
}

