class _VideoCircleCutoutPainter extends CustomPainter {
final Color overlayColor;
const _VideoCircleCutoutPainter({required this.overlayColor});

@override
void paint(Canvas canvas, Size size) {
final path = Path()..addRect(Rect.fromLTWH(0, 0, size.width, size.height));
final center = Offset(size.width / 2, size.height / 2);
final radius = size.shortestSide / 2;
path.addOval(Rect.fromCircle(center: center, radius: radius));
path.fillType = PathFillType.evenOdd;
canvas.drawPath(path, Paint()..color = overlayColor);
}

@override
bool shouldRepaint(covariant _VideoCircleCutoutPainter oldDelegate) => oldDelegate.overlayColor != overlayColor;
}

class _VideoTrimPage extends StatefulWidget {
final String sourcePath;
const _VideoTrimPage({required this.sourcePath});
@override
State<_VideoTrimPage> createState() => _VideoTrimPageState();
}

// Trim video pakai FFmpeg (software encode via libx264), bukan native
// hardware encoder (MediaCodec/Media3) seperti sebelumnya. Hardware encoder
// di sebagian chipset (mis. MediaTek Helio G88 di Infinix Hot 11 NFC)
// terbukti crash native tanpa exception apapun yang bisa ditangkap Dart,
// berapa pun resolusi/durasi videonya (sudah diuji sampai 576p tetap
// crash). Software encode tidak bergantung ke hardware encoder OEM sama
// sekali, sedikit lebih lambat tapi jauh lebih portable lintas device.
class _VideoTrimPageState extends State<_VideoTrimPage> {
VideoPlayerController? _controller;
bool _saving = false;
bool _failed = false;
double _progress = 0.0;
double _startMs = 0;
double _endMs = 15000;
double _durationMs = 15000;
static const double _maxTrimMs = 15000;

@override
void initState() {
super.initState();
_setup();
}

Future<void> _setup() async {
final controller = VideoPlayerController.file(File(widget.sourcePath));
try {
await controller.initialize();
} catch (_) {
controller.dispose();
if (mounted) setState(() => _failed = true);
return;
}
if (!mounted) {
controller.dispose();
return;
}
final totalMs = controller.value.duration.inMilliseconds.toDouble();
final clampedEnd = totalMs < _maxTrimMs ? totalMs : _maxTrimMs;
setState(() {
_controller = controller;
_durationMs = totalMs <= 0 ? _maxTrimMs : totalMs;
_startMs = 0;
_endMs = clampedEnd <= 0 ? _maxTrimMs : clampedEnd;
});
controller.setLooping(true);
controller.play();
}

@override
void dispose() {
_controller?.dispose();
super.dispose();
}

void _onRangeChanged(RangeValues values) {
var start = values.start;
var end = values.end;
if (end - start > _maxTrimMs) {
// Jaga rentang trim maksimal 15 detik: kalau geser salah satu ujung
// sampai melebihi batas, geser ujung yang sama arah supaya rentang
// tetap <= 15 detik alih-alih menolak gesture begitu saja.
if (start != _startMs) {
end = start + _maxTrimMs;
} else {
start = end - _maxTrimMs;
}
}
setState(() {
_startMs = start;
_endMs = end;
});
_controller?.seekTo(Duration(milliseconds: _startMs.round()));
}

Future<void> _save() async {
final controller = _controller;
if (controller == null || _endMs <= _startMs) return;
setState(() {
_saving = true;
_progress = 0.0;
});
controller.pause();
final startSec = _startMs / 1000;
final durationSec = (_endMs - _startMs) / 1000;
final dir = await getTemporaryDirectory();
final outputPath = '${dir.path}/trimmed_${DateTime.now().microsecondsSinceEpoch}.mp4';

// Percobaan 1: hardware encoder (h264_mediacodec) — memakai chip encode
// dedicated di SoC, jauh lebih cepat & hemat baterai dibanding software.
// Ini BERBEDA dari implementasi lama yang crash native (pemakaian
// MediaCodec API mentah tanpa FFmpeg): FFmpeg membungkus MediaCodec
// dengan penanganan error yang lebih baik, sehingga kegagalan biasanya
// dilaporkan lewat return code, bukan crash proses. CATATAN: kalau
// ternyata tetap terjadi crash native murni di device tertentu, itu
// tidak bisa ditangkap try-catch apa pun (proses mati sebelum sempat
// fallback) — tapi ini risiko yang jauh lebih kecil lewat jalur FFmpeg.
final hwCommand = '-y -i "${widget.sourcePath}" -ss $startSec -t $durationSec '
'-vf "scale=\'min(1280,iw)\':-2" -c:v h264_mediacodec -b:v 8M '
'-pix_fmt yuv420p -c:a aac -b:a 128k -movflags +faststart "$outputPath"';

// Percobaan 2 (fallback): software encoder libx264 — lebih lambat tapi
// tidak bergantung sama sekali ke driver hardware OEM, jadi selalu
// portable lintas device kalau hardware encoder gagal/tidak didukung.
final swCommand = '-y -i "${widget.sourcePath}" -ss $startSec -t $durationSec '
'-vf "scale=\'min(1280,iw)\':-2" -c:v libx264 -preset veryfast -crf 23 '
'-threads 0 -pix_fmt yuv420p -c:a aac -b:a 128k -movflags +faststart "$outputPath"';

await _appendDartCrashLog('[Checkpoint ${DateTime.now()}] FFmpegTrim: START start=$startSec dur=$durationSec');
ReturnCode? returnCode;
try {
returnCode = await _runFfmpegTrim(hwCommand, durationSec);
await _appendDartCrashLog('[Checkpoint ${DateTime.now()}] FFmpegTrim: HW rc=$returnCode');

if (!ReturnCode.isSuccess(returnCode)) {
if (mounted) setState(() => _progress = 0.0);
returnCode = await _runFfmpegTrim(swCommand, durationSec);
await _appendDartCrashLog('[Checkpoint ${DateTime.now()}] FFmpegTrim: SW-fallback rc=$returnCode');
}

if (!mounted) return;
setState(() => _saving = false);
if (ReturnCode.isSuccess(returnCode)) {
Navigator.pop(context, outputPath);
} else {
ScaffoldMessenger.of(context).showSnackBar(
const SnackBar(content: Text('Gagal memotong video, coba lagi.')),
);
}
} catch (e) {
await _appendDartCrashLog('[Checkpoint ${DateTime.now()}] FFmpegTrim: EXCEPTION $e');
if (!mounted) return;
setState(() => _saving = false);
ScaffoldMessenger.of(context).showSnackBar(
const SnackBar(content: Text('Gagal memotong video, coba lagi.')),
);
}
}

Future<ReturnCode?> _runFfmpegTrim(String command, double durationSec) async {
final completer = Completer<ReturnCode?>();
await FFmpegKit.executeAsync(
command,
(session) async {
final rc = await session.getReturnCode();
if (!completer.isCompleted) completer.complete(rc);
},
null,
(statistics) {
if (!mounted || durationSec <= 0) return;
final processedMs = statistics.getTime();
final progress = (processedMs / (durationSec * 1000)).clamp(0.0, 1.0);
setState(() => _progress = progress);
},
);
return completer.future;
}

String _fmt(double ms) {
final d = Duration(milliseconds: ms.round());
final m = d.inMinutes.remainder(60).toString().padLeft(2, '0');
final s = d.inSeconds.remainder(60).toString().padLeft(2, '0');
return '$m:$s';
}

