List<FinanceTransaction> _buildSmartDummyTransactions(List<FinanceCard> cards) {
final now = DateTime.now();
final seed = now.microsecondsSinceEpoch;
final list = <FinanceTransaction>[];
for (var i = 0; i < cards.length; i++) {
