ConsumerState<FinanceShell> createState() => _FinanceShellState();
}

class _FinanceShellState extends ConsumerState<FinanceShell> with SingleTickerProviderStateMixin {
late final PageController _pageController;
late final AnimationController _fadeController;
late final Animation<double> _fadeAnimation;

@override
void initState() {
super.initState();
_pageController = PageController(initialPage: ref.read(tabProvider));
// Kurangi durasi menjadi 100ms agar fade out & in lebih responsif (total 200ms)
_fadeController = AnimationController(vsync: this, duration: const Duration(milliseconds: 100));
_fadeAnimation = CurvedAnimation(parent: _fadeController, curve: Curves.easeInOut);
}

@override
void dispose() {
_pageController.dispose();
_fadeController.dispose();
super.dispose();
}

@override
Widget build(BuildContext context) {
final tab = ref.watch(tabProvider);
final lang = ref.watch(langProvider);
ref.listen<int>(tabProvider, (previous, next) {
if (!_pageController.hasClients) return;
final current = _pageController.page?.round() ?? tab;
if (current != next) {
if ((current - next).abs() == 1) {
_pageController.animateToPage(
next,
duration: const Duration(milliseconds: 300),
curve: Curves.easeOutCubic,
);
} else {
_fadeController.forward(from: 0).whenComplete(() {
if (mounted) {
_pageController.jumpToPage(next);
_fadeController.reverse();
}
});
}
}
});
return Scaffold(
body: FadeTransition(
opacity: ReverseAnimation(_fadeAnimation),
child: PageView(
controller: _pageController,
onPageChanged: (i) => ref.read(tabProvider.notifier).state = i,
children: FinanceShell.pages.map((p) => RepaintBoundary(child: p)).toList(),
),
),
bottomNavigationBar: Consumer(
builder: (context, ref, child) {
final previewProgress = ref.watch(profilePreviewProgressProvider);
final opacity = (1.0 - previewProgress).clamp(0.0, 1.0);

return IgnorePointer(
ignoring: opacity == 0.0,
child: Container(
foregroundDecoration: BoxDecoration(
color: Colors.black.withOpacity(previewProgress),
),
decoration: BoxDecoration(
color: context.cardColor,
border: Border(top: BorderSide(color: context.borderColor)),
),
padding: const EdgeInsets.only(top: 12, bottom: 20),
child: Opacity(
opacity: opacity,
child: Row(
mainAxisAlignment: MainAxisAlignment.spaceEvenly,
children: [
_navItem(context, 0, SolarIconsOutline.home, SolarIconsBold.home, Strings.t(lang, 'nav_home'), tab, ref),
_navItem(context, 1, SolarIconsOutline.chart, SolarIconsBold.chart, Strings.t(lang, 'nav_statistic'), tab, ref),
GestureDetector(
onTap: () => pickReceiptFromCameraAndPush(context),
child: Container(
