// ---- LAYER 2: Sheet Surface (Scroll View) (Paling Atas) ----
// Container dengan warna solid sehingga akan memblok/menutupi
// Layer 1 secara natural saat terscroll ke atas
//
// FASE 2 rubber: Transform.scale (anchor atas) memberi efek
// regangan elastis tipis pada sheet (sheetRubberScale), TIDAK
// mengubah urutan layer — Sheet tetap selalu di depan Media.
Transform.scale(
alignment: Alignment.topCenter,
scale: sheetRubberScale,
child: Opacity(
opacity: sheetOpacity,
child: NotificationListener<ScrollNotification>(
onNotification: _handleScrollNotification,
child: CustomScrollView(
controller: _scrollController,
physics: _HeaderSnapScrollPhysics(
boundary: _maxExpandScroll,
isLocked: () => _gestureCrossingLocked,
hasMedia: () => ref.read(userProfileProvider).hasPhoto || ref.read(userProfileProvider).hasVideo,
allowPreviewEntry: () => _gestureAllowsPreviewEntry,
maxTopRubberOffset: _rubberMaxRawOffset,
parent: const ClampingScrollPhysics(parent: AlwaysScrollableScrollPhysics()),
),
slivers: [
SliverToBoxAdapter(
// Spacer SELALU konstan 360px, tidak pernah bergantung pada
// _scrollOffset lagi. Kompensasi posisi sheet saat rubber
// overscroll sekarang dilakukan lewat Transform.translate
// pada konten sliver berikutnya (lihat di bawah) — ini
// memperbaiki bug scroll auto naik-turun yang disebabkan
// oleh perubahan tinggi layout berbasis scroll offset.
child: const SizedBox(height: 360.0),
),
SliverToBoxAdapter(
child: Transform.translate(
// Menggeser konten ke atas sebesar overscroll Fase 2
// (sheetSpacerCompensation), meniru efek "terpaku" yang
// dulu dicapai dengan memangkas tinggi spacer. Transform
// HANYA mengubah posisi gambar (paint) dan TIDAK PERNAH
// mengubah ukuran layout sliver ini, sehingga tidak akan
// memicu applyNewDimensions()/reset ballistic setiap
// frame — sumber bug scroll "jalan sendiri" sebelumnya.
offset: Offset(0, -sheetSpacerCompensation),
child: Stack(
clipBehavior: Clip.none,
children: [
// Layer Background: memanjang jauh ke bawah untuk selalu menutupi area kosong
// saat overscroll terjadi, TANPA menambah area scrollable (maxScrollExtent).
