// batal dipanggil, transaksi tidak benar-benar terhapus, dan saldo utama tidak
// ter-update meski item sudah tidak terlihat di daftar.
child: IgnorePointer(
ignoring: isRemoving,
child: ConstrainedBox(
constraints: isRemoving ? const BoxConstraints(maxHeight: 0) : const BoxConstraints(),
child: ClipRect(child: child),
