class _ConfettiOverlay extends StatefulWidget {
  final VoidCallback onDone;
  const _ConfettiOverlay({required this.onDone});
  @override
  State<_ConfettiOverlay> createState() => _ConfettiOverlayState();
}

class _ConfettiOverlayState extends State<_ConfettiOverlay> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(vsync: this, duration: const Duration(milliseconds: 1700));
  late final List<_ConfettiParticle> _particles;
  static const _colors = [Color(0xFF24A148), Color(0xFF7655D8), Color(0xFFE05270), Color(0xFFFFC107), Color(0xFF2196F3)];

  @override
  void initState() {
    super.initState();
    final rnd = Random();
    _particles = List.generate(26, (i) => _ConfettiParticle(
          x: rnd.nextDouble(),
          startDelay: rnd.nextDouble() * 0.25,
          swaySeed: rnd.nextDouble() * pi * 2,
          sizeSeed: 5 + rnd.nextDouble() * 5,
          color: _colors[rnd.nextInt(_colors.length)],
        ));
    _controller.forward().whenComplete(() {
      if (mounted) widget.onDone();
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    return Positioned.fill(
      child: IgnorePointer(
        child: AnimatedBuilder(
          animation: _controller,
          builder: (context, child) => CustomPaint(
            size: size,
            painter: _ConfettiPainter(particles: _particles, progress: _controller.value),
          ),
        ),
      ),
    );
  }
}

class _ConfettiPainter extends CustomPainter {
  final List<_ConfettiParticle> particles;
  final double progress;
  _ConfettiPainter({required this.particles, required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    for (final p in particles) {
      final localT = ((progress - p.startDelay) / (1 - p.startDelay)).clamp(0.0, 1.0);
      if (localT <= 0) continue;
      final dy = size.height * 0.32 * localT;
      final dx = sin(p.swaySeed + localT * pi * 3) * 22;
      final opacity = (1 - localT).clamp(0.0, 1.0);
      final paint = Paint()..color = p.color.withOpacity(opacity);
      final cx = p.x * size.width + dx;
      final cy = size.height * 0.22 + dy;
      canvas.save();
      canvas.translate(cx, cy);
      canvas.rotate(localT * pi * 4);
      canvas.drawRect(Rect.fromCenter(center: Offset.zero, width: p.sizeSeed, height: p.sizeSeed * 0.6), paint);
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant _ConfettiPainter oldDelegate) => oldDelegate.progress != progress;
}

class CountUpNumberFlow extends StatefulWidget {
  final num value;
  final String locale;
  final NumberFlowFormat format;
  final TextStyle style;
  final bool tabularNums;
  const CountUpNumberFlow({
    super.key,
    required this.value,
    required this.locale,
    required this.format,
    required this.style,
    this.tabularNums = true,
  });

  @override
  State<CountUpNumberFlow> createState() => _CountUpNumberFlowState();
}

class _CountUpNumberFlowState extends State<CountUpNumberFlow> {
  num _displayValue = 0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) setState(() => _displayValue = widget.value);
    });
  }

  @override
  void didUpdateWidget(covariant CountUpNumberFlow oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.value != widget.value) {
      _displayValue = widget.value;
    }
  }

  @override
  Widget build(BuildContext context) {
    return NumberFlow(
      value: _displayValue,
      locale: widget.locale,
      format: widget.format,
      spring: NumberFlowSpring.ios,
      transformTiming: const TimingConfig(duration: Duration(milliseconds: 450), curve: Curves.easeInOut),
      opacityTiming: const TimingConfig(duration: Duration(milliseconds: 450), curve: Curves.easeOut),
      tabularNums: widget.tabularNums,
      style: widget.style,
    );
  }
}

class LiquidGlass extends StatelessWidget {
  final Widget child;
  final double borderRadius;
  final Color? tint;
  final double blur;
  final double intensity;
  final bool useBlur;
  final Color? borderColor;
  final double chromaticAberration;

  const LiquidGlass({super.key, required this.child, this.borderRadius = 20, this.tint, this.blur = 6, this.intensity = 1.0, this.useBlur = false, this.borderColor, this.chromaticAberration = 0.0});

  @override
  Widget build(BuildContext context) {
    final isDark = context.isDark;
    final base = tint ?? Colors.white;
    final rimColor = borderColor ?? Colors.white.withOpacity(isDark ? 0.45 : 0.85);

    if (!useBlur) {
      final opacity = ((isDark ? 0.34 : 0.86) * intensity).clamp(0.0, 1.0);
      return Container(
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(borderRadius),
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              base.withOpacity((opacity + 0.10).clamp(0.0, 1.0)),
              base.withOpacity(opacity),
            ],
          ),
          border: Border.all(color: rimColor, width: 1.2),
          boxShadow: [
            BoxShadow(color: Colors.black.withOpacity(isDark ? 0.28 : 0.12), blurRadius: 10, spreadRadius: -1, offset: const Offset(0, 3)),
          ],
        ),
        child: child,
      );
    }

    final glassOpacity = ((isDark ? 0.38 : 0.30) * intensity).clamp(0.0, 1.0);
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(borderRadius),
        border: Border.all(color: rimColor, width: 1.2),
        boxShadow: [
          BoxShadow(color: Colors.black.withOpacity(isDark ? 0.28 : 0.12), blurRadius: 10, spreadRadius: -1, offset: const Offset(0, 3)),
        ],
      ),
      child: GlassContainer(
        shape: LiquidRoundedRectangle(borderRadius: borderRadius),
        useOwnLayer: true,
        quality: GlassQuality.premium,
        settings: LiquidGlassSettings(
          glassColor: base.withOpacity(glassOpacity),
          blur: blur,
          thickness: 30,
          refractiveIndex: 1.85,
          lightIntensity: isDark ? 1.1 : 1.35,
          lightAngle: 2.4,
          ambientStrength: isDark ? 0.5 : 0.68,
          chromaticAberration: chromaticAberration,
          whitenStrength: isDark ? 0.0 : 0.4,
          saturation: 1.15,
          shadowElevation: isDark ? 1 : 4,
        ),
        child: child,
      ),
    );
  }
}


class VisibilityAwareLottie extends StatefulWidget {
  final String asset;
  const VisibilityAwareLottie({super.key, required this.asset});

  @override
  State<VisibilityAwareLottie> createState() => _VisibilityAwareLottieState();
}

class _VisibilityAwareLottieState extends State<VisibilityAwareLottie> with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(vsync: this);
  late final Key _visibilityKey = UniqueKey();
  bool _isVisible = true;

  @override
  void dispose() {
    VisibilityDetectorController.instance.forget(_visibilityKey);
    _controller.dispose();
    super.dispose();
  }

  void _handleVisibility(VisibilityInfo info) {
    if (!mounted) return;
    final visible = info.visibleFraction > 0.04;
    if (visible == _isVisible) return;
    _isVisible = visible;
    if (visible) {
      _controller.repeat();
    } else {
      _controller.stop();
    }
  }

  @override
  Widget build(BuildContext context) {
    return VisibilityDetector(
      key: _visibilityKey,
      onVisibilityChanged: _handleVisibility,
      child: Lottie.asset(
        widget.asset,
        controller: _controller,
        onLoaded: (composition) {
          _controller.duration = composition.duration;
          if (_isVisible) _controller.repeat();
        },
        fit: BoxFit.cover,
      ),
    );
  }
}

const _shakeEase = Cubic(0.22, 1, 0.36, 1);

class ShakeField extends StatefulWidget {
  final Widget child;
  const ShakeField({super.key, required this.child});
  @override
  State<ShakeField> createState() => ShakeFieldState();
}

class ShakeFieldState extends State<ShakeField> with SingleTickerProviderStateMixin {
  late final AnimationController _controller =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 280));
  late final Animation<double> _offset = TweenSequence<double>([
    TweenSequenceItem(tween: Tween(begin: 0.0, end: 6.0).chain(CurveTween(curve: _shakeEase)), weight: 80),
    TweenSequenceItem(tween: Tween(begin: 6.0, end: -6.0).chain(CurveTween(curve: _shakeEase)), weight: 80),
    TweenSequenceItem(tween: Tween(begin: -6.0, end: 4.0).chain(CurveTween(curve: _shakeEase)), weight: 60),
    TweenSequenceItem(tween: Tween(begin: 4.0, end: 0.0).chain(CurveTween(curve: _shakeEase)), weight: 60),
  ]).animate(_controller);

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void shake() => _controller.forward(from: 0);

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _offset,
      builder: (context, child) => Transform.translate(offset: Offset(_offset.value, 0), child: child),
      child: widget.child,
    );
  }
}

class PressScale extends StatefulWidget {
  final Widget child;
  final VoidCallback onTap;
  final VoidCallback? onLongPress;
  const PressScale({super.key, required this.child, required this.onTap, this.onLongPress});
  @override
  State<PressScale> createState() => _PressScaleState();
}

class _PressScaleState extends State<PressScale> {
  double _scale = 1.0;

  void _setPressed(bool pressed) {
    setState(() => _scale = pressed ? 0.92 : 1.0);
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTapDown: (_) => _setPressed(true),
      onTapUp: (_) => _setPressed(false),
      onTapCancel: () => _setPressed(false),
      onTap: () {
        HapticFeedback.selectionClick();
        widget.onTap();
      },
      onLongPress: widget.onLongPress,
      behavior: HitTestBehavior.opaque,
      child: AnimatedScale(
        scale: _scale,
        duration: const Duration(milliseconds: 120),
        curve: Curves.easeOut,
        child: widget.child,
      ),
    );
  }
}

