class OnboardingPage extends ConsumerStatefulWidget {
  const OnboardingPage({super.key});
  @override
  ConsumerState<OnboardingPage> createState() => _OnboardingPageState();
}

class _OnboardingPageState extends ConsumerState<OnboardingPage> {
  late final PageController _pageController = PageController();
  final _nameCtrl = TextEditingController();
  final _nameShakeKey = GlobalKey<ShakeFieldState>();
  final _avatarShakeKey = GlobalKey<ShakeFieldState>();
  int _currentPage = 0;
  String? _nameError;

  final slideKeys = const [
    ('onboarding_title_1', 'onboarding_desc_1', SolarIconsBold.wallet),
    ('onboarding_title_2', 'onboarding_desc_2', SolarIconsBold.billList),
    ('onboarding_title_3', 'onboarding_desc_3', SolarIconsBold.chart),
  ];

  @override
  void dispose() {
    _pageController.dispose();
    _nameCtrl.dispose();
    super.dispose();
  }

  void _finish() {
    final name = _nameCtrl.text.trim();
    final profile = ref.read(userProfileProvider);
    final lang = ref.read(langProvider);

    if (!profile.hasPhoto && !profile.hasVideo) {
      _avatarShakeKey.currentState?.shake();
      showGlassSnackBar(context, Strings.t(lang, 'profile_picture_required'), icon: Icons.warning_amber_rounded);
      return;
    }

    if (name.isEmpty) {
      setState(() => _nameError = Strings.t(lang, 'field_required'));
      _nameShakeKey.currentState?.shake();
      Future.delayed(const Duration(milliseconds: 3000), () {
        if (mounted) setState(() => _nameError = null);
      });
      return;
    }
    ref.read(userProfileProvider.notifier).updateName(name);
    ref.read(prefsProvider).setBool('onboarding_done', true);
    ref.read(onboardingProvider.notifier).state = true;
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    final lang = ref.watch(langProvider);
    final isDark = context.isDark;

    return Scaffold(
      body: SafeArea(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(28, 24, 28, 0),
              child: Row(
