class TransactionsPage extends ConsumerStatefulWidget {
  const TransactionsPage({super.key});
  @override
  ConsumerState<TransactionsPage> createState() => _TransactionsPageState();
}
class _TransactionsPageState extends ConsumerState<TransactionsPage> with TickerProviderStateMixin {
  String query = '';
  String filter = 'all';
  int? cardFilter;
  double minAmountFilter = 0;
  bool _sliderDragging = false;
  bool _minAmountExpanded = false;
  int _displayCount = _pageSize;
  final ScrollController _scrollController = ScrollController();
  final ValueNotifier<num> _minAmountNotifier = ValueNotifier<num>(0);
  static const filterKeys = ['all', 'income', 'expense'];
  static const _pageSize = 10;
  static const _maxAmountFilter = 5000000.0;

  @override
  void initState() {
    super.initState();
    _scrollController.addListener(_onScroll);
  }

  @override
  void dispose() {
    _scrollController.removeListener(_onScroll);
    _scrollController.dispose();
    _minAmountNotifier.dispose();
    super.dispose();
  }

  void _onScroll() {
    if (!_scrollController.hasClients) return;
    final threshold = _scrollController.position.maxScrollExtent - 200;
    if (_scrollController.position.pixels >= threshold) {
      setState(() => _displayCount += _pageSize);
    }
  }

  void _resetPaging() {
    _displayCount = _pageSize;
  }

  @override
  Widget build(BuildContext context) {
    final all = ref.watch(transactionsProvider);
    final lang = ref.watch(langProvider);
    final cards = ref.watch(cardsProvider);
    final items = all.where((e) =>
        (filter == 'all' || (filter == 'income' ? e.income : !e.income)) &&
        (cardFilter == null || e.cardIndex == cardFilter) &&
        (!_minAmountExpanded || e.amount >= minAmountFilter) &&
        e.title.toLowerCase().contains(query.toLowerCase())).toList();
    final visibleCount = _displayCount < items.length ? _displayCount : items.length;
    final hasMore = visibleCount < items.length;
    return SafeArea(top: false, child: ListView.builder(
      controller: _scrollController,
      padding: EdgeInsets.fromLTRB(0, MediaQuery.paddingOf(context).top + 22, 0, 24),
      cacheExtent: 600,
      itemCount: visibleCount + 1 + (hasMore ? 1 : 0),
      itemBuilder: (context, index) {
        if (index == 0) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(Strings.t(lang, 'transactions_title'), style: TextStyle(fontFamily: 'DM Serif Display', fontSize: 32, color: context.textPrimary)),
                    Text(Strings.t(lang, 'transactions_subtitle'), style: TextStyle(color: context.textMuted)),
                    const SizedBox(height: 22),
                    GlassSearchBar(
                      placeholder: Strings.t(lang, 'search_transactions'),
                      quality: GlassQuality.standard,
                      onChanged: (v) => setState(() { query = v; _resetPaging(); }),
                    ),
                    const SizedBox(height: 14),
                    GlassSegmentedControl(
                      segments: filterKeys
                          .map((k) => GlassSegment(label: Strings.t(lang, 'filter_$k')))
                          .toList(),
                      selectedIndex: filterKeys.indexOf(filter),
                      indicatorColor: Theme.of(context).colorScheme.primary.withOpacity(context.isDark ? 0.25 : 0.15),
                      onSegmentSelected: (index) {
                        setState(() {
                          filter = filterKeys[index];
                          _resetPaging();
                        });
                      },
                      quality: GlassQuality.premium,
                    ),
                    const SizedBox(height: 10),
                  ],
                ),
              ),
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                padding: const EdgeInsets.symmetric(horizontal: 20),
                child: Row(
                  children: [
                    Padding(
                      padding: const EdgeInsets.only(right: 8),
                      child: ChoiceChip(
                        label: Text(Strings.t(lang, 'all_accounts')),
                        selected: cardFilter == null,
                        shape: const StadiumBorder(),
                        onSelected: (_) => setState(() { cardFilter = null; _resetPaging(); }),
                      ),
                    ),
                    ...cards.asMap().entries.map(
                          (e) => Padding(
                            padding: const EdgeInsets.only(right: 8),
                            child: ChoiceChip(
                              label: Text(e.value.name),
                              selected: cardFilter == e.key,
                              shape: const StadiumBorder(),
                              onSelected: (_) => setState(() { cardFilter = e.key; _resetPaging(); }),
                            ),
                          ),
                        ),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const SizedBox(height: 18),
                    GestureDetector(
                      behavior: HitTestBehavior.opaque,
                      onTap: () => setState(() => _minAmountExpanded = !_minAmountExpanded),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text('Nominal minimal', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: context.textMuted)),
                              const SizedBox(width: 4),
                              AnimatedRotation(
                                turns: _minAmountExpanded ? 0.5 : 0.0,
                                duration: const Duration(milliseconds: 200),
                                child: Icon(SolarIconsOutline.altArrowDown, size: 14, color: context.iconMuted),
                              ),
                            ],
                          ),
                          if (_minAmountExpanded)
                            NumberFlow.scrub(
                              value: _minAmountNotifier,
                              format: const NumberFlowFormat.currency(currencyCode: 'IDR', symbol: 'Rp '),
                              tabularNums: true,
                              style: TextStyle(fontFamily: 'Satoshi', fontSize: 12, fontWeight: FontWeight.w800, color: Theme.of(context).colorScheme.primary),
                            ),
                        ],
                      ),
                    ),
                    AnimatedCrossFade(
                      duration: const Duration(milliseconds: 220),
                      crossFadeState: _minAmountExpanded ? CrossFadeState.showSecond : CrossFadeState.showFirst,
                      firstChild: const SizedBox(width: double.infinity, height: 0),
                      secondChild: Padding(
                        padding: const EdgeInsets.only(top: 4),
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 15),
                          child: LayoutBuilder(
                          builder: (context, constraints) {
                            const thumbRadius = 15.0;
                            const thumbWidth = thumbRadius * 2.6;
                            const thumbHeight = thumbRadius * 1.6;
                            const widgetHeight = thumbRadius * 2 + 16;
                            const sliderRightPadding = 14.0;
                            final trackWidth = constraints.maxWidth - sliderRightPadding - thumbRadius * 2;
                            final normalized = ((minAmountFilter - 0) / (_maxAmountFilter - 0)).clamp(0.0, 1.0);
                            final thumbCenterX = thumbRadius + trackWidth * normalized;
                            const topPosition = (widgetHeight - thumbHeight) / 2;
                            return Stack(
                              clipBehavior: Clip.none,
                              children: [
                                Positioned(
                                  left: thumbCenterX - thumbRadius,
                                  top: topPosition,
                                  child: IgnorePointer(
                                    child: AnimatedScale(
                                      scale: _sliderDragging ? 1.18 : 1.0,
                                      duration: const Duration(milliseconds: 160),
                                      curve: Curves.easeOut,
                                      child: Container(
                                        width: thumbWidth,
                                        height: thumbHeight,
                                        decoration: BoxDecoration(
                                          borderRadius: BorderRadius.circular(thumbHeight / 2),
                                          boxShadow: [
                                            BoxShadow(
                                              color: Colors.black.withOpacity(context.isDark ? 0.16 : 0.08),
                                              blurRadius: 3,
                                              offset: const Offset(0, 1),
                                            ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  ),
                                ),
                                Padding(
                                  padding: const EdgeInsets.only(right: 14),
                                  child: GlassSlider(
                                    value: minAmountFilter,
                                    min: 0,
                                    max: _maxAmountFilter,
                                    divisions: 20,
                                    activeColor: Theme.of(context).colorScheme.primary,
                                    quality: GlassQuality.premium,
                                    useOwnLayer: true,
                                    onChangeStart: (_) => setState(() => _sliderDragging = true),
                                    onChangeEnd: (_) => setState(() => _sliderDragging = false),
                                    onChanged: (v) {
                                      _minAmountNotifier.value = v;
                                      setState(() {
                                        minAmountFilter = v;
                                        _resetPaging();
                                      });
                                    },
                                  ),
                                ),
                              ],
                            );
                          },
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(height: 16),
                  ],
                ),
              ),
            ],
          );
        }
        if (hasMore && index == visibleCount + 1) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 20),
            child: Center(child: SizedBox(width: 22, height: 22, child: CircularProgressIndicator(strokeWidth: 2.4))),
          );
        }
        final e = items[index - 1];
        return Padding(
          padding: const EdgeInsets.symmetric(horizontal: 20),
          child: AnimatedTransactionTile(
            item: e,
            child: StaggeredReveal(
              animate: true,
              index: index - 1,
              child: TransactionTile(item: e),
            ),
          ),
        );
      },
    ));
  }
}

class ReportsPage extends ConsumerWidget {
  const ReportsPage({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final allItems = ref.watch(transactionsProvider);
    final lang = ref.watch(langProvider);
    final cards = ref.watch(cardsProvider);
    final rawSelectedCard = ref.watch(selectedCardProvider);
    final isAllAccounts = rawSelectedCard == -1;
    final safeSelectedCard = cards.isEmpty ? 0 : (rawSelectedCard >= cards.length ? cards.length - 1 : (rawSelectedCard < 0 ? 0 : rawSelectedCard));
    final items = isAllAccounts ? allItems : allItems.where((e) => e.cardIndex == safeSelectedCard).toList();
    final income = items.where((e) => e.income).fold<double>(0, (a, b) => a + b.amount);
    final expense = items.where((e) => !e.income).fold<double>(0, (a, b) => a + b.amount);
    final groups = <String, double>{};
    for (final item in items.where((e) => !e.income)) groups[item.category] = (groups[item.category] ?? 0) + item.amount;
    final safeGroups = Map<String, double>.fromEntries(groups.entries.where((e) => e.value > 0));
    return SafeArea(top: false, child: ListView(padding: EdgeInsets.fromLTRB(20, MediaQuery.paddingOf(context).top + 22, 20, 24), children: [
      Text(Strings.t(lang, 'reports_title'), style: TextStyle(fontFamily: 'DM Serif Display', fontSize: 32, color: context.textPrimary)),
      Text(AppFormatters.monthYear(lang).format(DateTime(2026, 8, 24)), style: TextStyle(color: context.textMuted)),
      const SizedBox(height: 6),
      Text(isAllAccounts ? Strings.t(lang, 'all_accounts') : (cards.isEmpty ? '' : cards[safeSelectedCard].name), style: TextStyle(color: context.textFaint, fontSize: 12, fontWeight: FontWeight.w600)),
      const SizedBox(height: 22),
      RepaintBoundary(child: SummaryCard(income: income, expense: expense)),
      const SizedBox(height: 24),
      SectionTitle(Strings.t(lang, 'cash_flow')),
      const SizedBox(height: 12),
      Builder(builder: (context) {
        final now = DateTime.now();
        final dailyNet = List<double>.generate(7, (i) {
          final day = DateTime(now.year, now.month, now.day).subtract(Duration(days: 6 - i));
          final dayIncome = items.where((e) => e.income && _isSameDay(e.date, day)).fold<double>(0, (a, b) => a + b.amount);
          final dayExpense = items.where((e) => !e.income && _isSameDay(e.date, day)).fold<double>(0, (a, b) => a + b.amount);
          return dayIncome - dayExpense;
        });
        final maxAbs = dailyNet.map((v) => v.abs()).fold<double>(1, (a, b) => a > b ? a : b);
        final chartPrimary = Theme.of(context).colorScheme.primary;
        return Container(
          height: 190,
          padding: const EdgeInsets.fromLTRB(12, 20, 20, 12),
          decoration: BoxDecoration(color: context.cardColor, borderRadius: BorderRadius.circular(24), border: Border.all(color: context.borderColor)),
          child: LineChart(
            LineChartData(
              minY: -maxAbs * 1.2,
              maxY: maxAbs * 1.2,
              gridData: FlGridData(
                show: true,
                drawVerticalLine: false,
                horizontalInterval: (maxAbs * 1.2) / 2,
                getDrawingHorizontalLine: (_) => FlLine(color: context.isDark ? Colors.white.withOpacity(0.08) : const Color(0xFFEDEAF2), strokeWidth: 1),
              ),
              titlesData: const FlTitlesData(show: false),
              borderData: FlBorderData(show: false),
              lineTouchData: LineTouchData(
                touchTooltipData: LineTouchTooltipData(
                  getTooltipColor: (_) => context.isDark ? Colors.black87 : Colors.white,
                  getTooltipItems: (spots) => spots.map((s) => LineTooltipItem(rupiah(s.y), TextStyle(color: chartPrimary, fontWeight: FontWeight.bold, fontSize: 11))).toList(),
                ),
              ),
              lineBarsData: [
                LineChartBarData(
                  spots: List.generate(dailyNet.length, (i) => FlSpot(i.toDouble(), dailyNet[i])),
                  isCurved: true,
                  curveSmoothness: 0.35,
                  color: chartPrimary,
                  barWidth: 4,
                  dotData: const FlDotData(show: false),
                  belowBarData: BarAreaData(show: true, color: chartPrimary.withOpacity(context.isDark ? 0.18 : 0.12)),
                ),
              ],
            ),
            duration: const Duration(milliseconds: 450),
            curve: Curves.easeInOut,
          ),
        );
      }),
      const SizedBox(height: 24),
      SectionTitle(Strings.t(lang, 'expense_by_category')),
      const SizedBox(height: 12),
      Container(padding: const EdgeInsets.all(18), decoration: BoxDecoration(color: context.cardColor, borderRadius: BorderRadius.circular(24), border: Border.all(color: context.borderColor)), child: safeGroups.isEmpty
          ? Padding(padding: const EdgeInsets.symmetric(vertical: 8), child: Text(Strings.t(lang, 'no_expenses_yet'), style: TextStyle(color: context.textMuted, fontSize: 13)))
          : Builder(builder: (context) {
              final entries = safeGroups.entries.toList();
              return ListView.builder(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: entries.length,
                itemBuilder: (context, index) {
                  final e = entries[index];
                  return StaggeredReveal(index: index, child: ReportRow(label: e.key, amount: e.value, total: expense));
                },
              );
            })),
    ]));
  }
}

class _HeaderSnapScrollPhysics extends ScrollPhysics {
  final double boundary;
  final bool Function() isLocked;
  final bool Function() hasMedia;
  final bool Function() allowPreviewEntry;
  final double maxTopRubberOffset;

  const _HeaderSnapScrollPhysics({
    required this.boundary,
    required this.isLocked,
    required this.hasMedia,
    required this.allowPreviewEntry,
    this.maxTopRubberOffset = 70.0,
    super.parent,
  });

  @override
  _HeaderSnapScrollPhysics applyTo(ScrollPhysics? ancestor) {
    return _HeaderSnapScrollPhysics(
      boundary: boundary,
      isLocked: isLocked,
      hasMedia: hasMedia,
      allowPreviewEntry: allowPreviewEntry,
      maxTopRubberOffset: maxTopRubberOffset,
      parent: buildParent(ancestor),
    );
  }

  @override
  double applyBoundaryConditions(ScrollMetrics position, double value) {
    // Catatan: clamp "gesture crossing lock" yang sebelumnya ada di sini
    // (menahan pixels tepat di `boundary` selama drag yang dimulai dari
    // area expanded) sengaja dihapus. Flag isLocked() (_gestureCrossingLocked)
    // di-reset ke false oleh ScrollEndNotification SEBELUM ballistic/spring
    // simulation sempat berjalan, sehingga clamp ini tidak pernah benar-benar
    // melindungi animasi snap dari overshoot — efek nyatanya hanya mengunci
    // drag jari yang MASIH berlangsung begitu offset menyentuh `boundary`,
    // membuat scroll ke konten sheet di bawahnya terasa tertahan padahal
    // masih ada ruang, sampai jari dilepas dan gesture baru dimulai.
    // Menghapus clamp ini membuat drag tunggal yang meng-collapse header lalu
    // lanjut men-scroll konten sheet terasa menyatu/mulus tanpa perlu
    // melepas jari terlebih dahulu.

    // FASE 2 (EXPANDED + RUBBER): gesture PERTAMA yang diteruskan melewati
    // batas full-expand (offset 0) TIDAK boleh menembus ke FASE 3 (full
    // preview) — lihat allowPreviewEntry & _handleScrollNotification. Alih-
    // alih di-freeze keras di 0, beri sedikit ruang overscroll elastis
    // (rubber) hingga maxTopRubberOffset; resistance-nya sendiri diberikan
    // lewat applyPhysicsToUserOffset di bawah, mirip pola overscroll bawah.
    if (value <= 0.0) {
      if (!allowPreviewEntry()) {
        final double minPos = -maxTopRubberOffset;
        if (value < minPos && position.pixels >= minPos) {
          return value - minPos;
        }
        if (minPos > position.pixels && position.pixels > value) {
          return value - position.pixels;
        }
      }
      // PENTING: setelah batas keras rubber di atas, offset negatif (baik
      // untuk rubber Fase 2 maupun full preview Fase 3) HARUS selalu
      // dibiarkan bebas (return 0.0 = tanpa correction) di sini, alih-alih
      // jatuh ke `super`/physics parent (ClampingScrollPhysics). Clamping
      // akan langsung mengunci pixels di 0 begitu value negatif, yang
      // mematikan efek scale gambar/video Fase 2 (mediaRubberProgress
      // selalu 0) sekaligus mematikan gesture full preview Fase 3.
      return 0.0;
    }

    // Batas bawah DIKUNCI KERAS (tanpa efek rubber/pantul sama sekali) —
    // berbeda dari batas atas Fase 2 yang sengaja tetap elastis.
    final maxPos = position.maxScrollExtent;
    if (maxPos <= position.pixels && position.pixels < value) {
      return value - maxPos;
    }
    if (position.pixels < maxPos && maxPos < value) {
      return value - maxPos;
    }

    return super.applyBoundaryConditions(position, value);
  }

  @override
  double applyPhysicsToUserOffset(ScrollMetrics position, double offset) {
    // FASE 2 rubber: resistance overscroll atas, semakin dalam ditarik
    // semakin besar hambatannya (mendekati maxTopRubberOffset). Batas
    // bawah tidak lagi punya efek rubber sama sekali (lihat
    // applyBoundaryConditions yang mengunci keras di maxScrollExtent).
    if (position.pixels < 0.0 && !allowPreviewEntry()) {
      final overscroll = -position.pixels;
      final fraction = (overscroll / maxTopRubberOffset).clamp(0.0, 1.0);
      final friction = 1.0 - (fraction * fraction);
      return super.applyPhysicsToUserOffset(position, offset) * friction;
    }
    return super.applyPhysicsToUserOffset(position, offset);
  }

  @override
  Simulation? createBallisticSimulation(ScrollMetrics position, double velocity) {
    // 1. Pull down to preview snap (HANYA untuk gesture yang diizinkan masuk
    // FASE 3 / full preview; selain itu selalu kembali ke EXPANDED (0.0) —
    // termasuk saat melepas jari di tengah rubber effect FASE 2).
    if (position.pixels < 0.0) {
      if (allowPreviewEntry() && hasMedia() && (position.pixels <= -50.0 || (velocity < -500.0 && position.pixels < -15.0))) {
        return ScrollSpringSimulation(
          spring,
          position.pixels,
          -100.0,
          velocity,
          tolerance: toleranceFor(position),
        );
      } else {
        return ScrollSpringSimulation(
          spring,
          position.pixels,
          0.0,
          velocity,
          tolerance: toleranceFor(position),
        );
      }
    }

    // 2. Snap inside expansion area
    if (position.pixels > 0 && position.pixels < boundary) {
      if (velocity < -300.0) {
        return ScrollSpringSimulation(spring, position.pixels, 0.0, velocity, tolerance: toleranceFor(position));
      } else if (velocity > 300.0) {
        return ScrollSpringSimulation(spring, position.pixels, boundary, velocity, tolerance: toleranceFor(position));
      }

      final target = position.pixels > (boundary * 0.45) ? boundary : 0.0;
      return ScrollSpringSimulation(
        spring,
        position.pixels,
        target,
        velocity,
        tolerance: toleranceFor(position),
      );
    }

    return super.createBallisticSimulation(position, velocity);
  }
}

class ProfilePage extends ConsumerStatefulWidget {
  const ProfilePage({super.key});
  @override
  ConsumerState<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends ConsumerState<ProfilePage> {
  late final ScrollController _scrollController;
  bool _initialized = false;
  double _scrollOffset = 0.0;
  double _maxExpandScroll = 0.0;
  bool _gestureCrossingLocked = false;
  bool _gestureAllowsPreviewEntry = true;
  bool _previewPushed = false;

  // FASE 2 — EXPANDED + RUBBER EFFECT: state & batasan terpisah dari
  // mediaExpandProgress/previewProgress. Rubber tidak pernah mengubah
  // expanded state maupun membuka FULL PREVIEW; hanya feedback fisik
  // sementara yang kembali ke 0 saat gesture dilepas (lihat
  // _HeaderSnapScrollPhysics.createBallisticSimulation).
  static const double _rubberMaxRawOffset = 95.0;
  static const double _mediaRubberMaxExtraScale = 0.22;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (!_initialized) {
      final topInset = MediaQuery.paddingOf(context).top;
      // Posisi di mana Sheet akan berada ketika compact
      final compactHeight = topInset + 18.0 + 68.0 + 16.0;
      // Posisi awal Sheet (ruang kosong transparent) ketika di-expand, dikurangi overlap 20px
      final expandedSheetTop = 380.0 - 20.0; 

      _maxExpandScroll = expandedSheetTop - compactHeight;

      _scrollController = ScrollController(initialScrollOffset: _maxExpandScroll);
      _scrollOffset = _maxExpandScroll;

      _scrollController.addListener(() {
        if (!mounted) return;

        final newOffset = _scrollController.offset;
        setState(() {
          _scrollOffset = newOffset;
        });

        // previewProgress (scrim & opacity bottom nav) HANYA berlaku untuk
        // FASE 3 (gesture kedua yang diizinkan masuk preview). Offset
        // negatif dari FASE 2 (rubber) tidak boleh ikut memicu ini.
        final progress = (newOffset < 0 && _gestureAllowsPreviewEntry) ? (-newOffset / 100.0).clamp(0.0, 1.0) : 0.0;
        Future.microtask(() {
          if (mounted) {
            ref.read(profilePreviewProgressProvider.notifier).state = progress;
          }
        });

        if (_scrollOffset <= -98.0 && !_previewPushed && _gestureAllowsPreviewEntry) {
          final profile = ref.read(userProfileProvider);
          if (profile.hasPhoto || profile.hasVideo) {
            _previewPushed = true;
            Navigator.push(context, MediaPreviewRoute(builder: (_) => const ProfileMediaViewerPage())).then((_) {
              _previewPushed = false;
              if (mounted && _scrollController.hasClients) {
                _scrollController.jumpTo(0.0);
              }
              // Jaga-jaga: pastikan video header kembali melanjutkan
              // pemutaran (bukan freeze/pause) setelah preview fullscreen
              // ditutup, tanpa harus pindah tab dulu.
              final headerController = ProfileVideoManager.controller;
              if (headerController != null && headerController.value.isInitialized && !headerController.value.isPlaying) {
                headerController.play();
              }
            });
          }
        }
      });

      _initialized = true;
    }
  }

  @override
  void dispose() {
    _scrollController.dispose();
    Future.microtask(() {
      try {
        ref.read(profilePreviewProgressProvider.notifier).state = 0.0;
      } catch (_) {}
    });
    super.dispose();
  }

  void _collapseMediaNow() {
    if (_scrollController.hasClients) {
      _scrollController.animateTo(
        _maxExpandScroll,
        duration: const Duration(milliseconds: 400),
        curve: Curves.easeOutCubic,
      );
    }
  }

  bool _handleScrollNotification(ScrollNotification notification) {
    if (notification is ScrollStartNotification) {
      final currentOffset = _scrollController.hasClients ? _scrollController.offset : _maxExpandScroll;
      final startedBelowDefault = currentOffset < _maxExpandScroll - 0.5;
      final isRealDrag = notification.dragDetails != null;
      _gestureCrossingLocked = isRealDrag && startedBelowDefault;
      // Gesture (drag) baru hanya diizinkan masuk ke area preview (offset
      // negatif) jika dimulai saat header SUDAH berada di/lewat batas full
      // expand (offset <= 0). Jika dimulai dari posisi masih positif
      // (compact/setengah expand), gesture ini dikunci di batas 0 dan tidak
      // bisa menembus ke preview sampai jari dilepas & discroll ulang.
      if (isRealDrag) {
        _gestureAllowsPreviewEntry = currentOffset <= 0.5;
      }
    } else if (notification is ScrollEndNotification) {
      _gestureCrossingLocked = false;
    }
    return false;
  }

  @override
  Widget build(BuildContext context) {
    final lang = ref.watch(langProvider);
    final profile = ref.watch(userProfileProvider);
    final initial = profile.name.isNotEmpty ? profile.name.substring(0, 1).toUpperCase() : '?';
    final hasMedia = profile.hasPhoto || profile.hasVideo;
    final topInset = MediaQuery.paddingOf(context).top;
    final screenWidth = MediaQuery.sizeOf(context).width;

    double t = 1.0;
    double parallaxOffset = 0.0;
    double previewProgress = 0.0;
    double mediaRubberProgress = 0.0;
    // Seberapa besar konten sheet perlu digeser ke ATAS lewat
    // Transform.translate (BUKAN lagi memangkas tinggi spacer) agar posisi
    // sheet tetap terpaku di viewport yang sama walau scroll offset sedang
    // negatif (overscroll rubber Fase 2).
    // PENTING: nilai ini TIDAK PERNAH dipakai untuk mengubah ukuran/tinggi
    // widget apa pun di dalam CustomScrollView. Mengubah ukuran LAYOUT
    // berdasarkan _scrollOffset (cara lama) memicu
    // BallisticScrollActivity.applyNewDimensions() yang me-restart simulasi
    // ballistic setiap frame selama animasi snap — inilah penyebab bug
    // scroll "jalan sendiri" (naik-turun tanpa disentuh) di tab profile.
    // Transform hanya mengubah posisi gambar (paint), jadi aman dari bug ini.
    double sheetSpacerCompensation = 0.0;

    if (_scrollOffset > _maxExpandScroll) {
      t = 0.0;
      parallaxOffset = (_scrollOffset - _maxExpandScroll) * 1.0;
    } else if (_scrollOffset >= 0) {
      t = 1.0 - (_scrollOffset / _maxExpandScroll);
      parallaxOffset = 0.0;
    } else if (_gestureAllowsPreviewEntry) {
      // FASE 3 — FULL PREVIEW (hanya dari gesture kedua)
      t = 1.0;
      parallaxOffset = 0.0; 
      previewProgress = (-_scrollOffset / 100.0).clamp(0.0, 1.0);
    } else {
      // FASE 2 — EXPANDED + RUBBER EFFECT (gesture pertama diteruskan).
      // mediaExpandProgress (t) TETAP 1.0, rubber disimpan terpisah dan
      // tidak pernah membuka FULL PREVIEW.
      t = 1.0;
      parallaxOffset = 0.0;
      final double rawRubberProgress = (-_scrollOffset / _rubberMaxRawOffset).clamp(0.0, 1.0);
      mediaRubberProgress = rawRubberProgress;
      // Pangkas spacer sebesar overscroll (-_scrollOffset, positif) supaya
      // posisi konten sheet (yang dimulai tepat setelah spacer) tetap di
      // viewport-y yang sama persis seperti saat scrollOffset 0 — sheet
      // jadi terpaku, tidak ikut turun & tidak lepas dari overlap media.
      sheetSpacerCompensation = -_scrollOffset;
    }

    final double screenHeight = MediaQuery.sizeOf(context).height;

    double avatarWidth;
    double avatarHeight;
    double avatarRadius;
    double avatarTop;
    double avatarLeft;

    if (previewProgress > 0.0) {
      final targetHeight = screenWidth;
      final targetTop = (screenHeight - targetHeight) / 2;

      avatarWidth = screenWidth;
      avatarHeight = lerpDouble(380.0, targetHeight, previewProgress)!;
      avatarTop = lerpDouble(0.0, targetTop, previewProgress)!;
      avatarLeft = 0.0;
      avatarRadius = 0.0;
    } else {
      avatarWidth = lerpDouble(68.0, screenWidth, t)!;
      avatarHeight = lerpDouble(68.0, 380.0, t)!;
      avatarRadius = lerpDouble(34.0, 0, t)!;
      avatarTop = lerpDouble(topInset + 18.0, 0.0, t)!;
      avatarLeft = lerpDouble(20.0, 0.0, t)!;
    }

    final double compactRowOpacity = (1 - t * 2.6).clamp(0.0, 1.0);
    final double expandedCaptionOpacity = (((t - 0.45) / 0.55).clamp(0.0, 1.0)) * (1.0 - previewProgress);
    final double badgeOpacity = (1 - t * 5).clamp(0.0, 1.0);
    final double chevronOpacity = (((t - 0.5) / 0.5).clamp(0.0, 1.0)) * (1.0 - previewProgress);
    final int scrimAlpha = (0x99 * t * (1.0 - previewProgress)).round();
    final double sheetOpacity = 1.0 - previewProgress;
    // FASE 2 rubber: scale media & offset sheet berasal dari
    // mediaRubberProgress / sheetRubberProgress (lihat blok if/else di
    // atas), bukan dari t atau previewProgress.
    final double mediaRubberScale = 1.0 + mediaRubberProgress * _mediaRubberMaxExtraScale;
    // Efek rubber pada sheet: regangan skala kecil (bukan translate) yang
    // di-anchor dari sisi atas, jadi sheet tetap menempel/overlap dengan
    // media persis di titik yang sama, hanya meregang tipis ke bawah —
    // tidak pernah membuka celah di box-nya sendiri seperti translate.
    final double sheetRubberScale = 1.0 + mediaRubberProgress * 0.03;

    final isDark = context.isDark;
    final primary = Theme.of(context).colorScheme.primary;
    final profileScaffoldBg = isDark ? const Color(0xFF17141D) : const Color(0xFFEFEAFB);
    final Color currentScaffoldBg = Color.lerp(profileScaffoldBg, Colors.black, previewProgress)!;

    return Scaffold(
      backgroundColor: currentScaffoldBg,
      body: Stack(
        children: [
          // ---- LAYER 1: Background Media & Profile Identity (Paling Bawah) ----
          // Translasi akan membuatnya bergerak ke atas secara seragam dengan scroll
          Positioned(
            top: 0, left: 0, right: 0, bottom: 0,
            child: Transform.translate(
              offset: Offset(0, -parallaxOffset),
              child: Stack(
                clipBehavior: Clip.none,
                children: [
                  Positioned(
                    top: avatarTop,
                    left: avatarLeft,
                    width: avatarWidth,
                    height: avatarHeight,
                    // FASE 2 rubber: Transform.scale memberi efek "bulge"
                    // elastis sementara (mediaRubberScale) TANPA mengubah
                    // avatarWidth/avatarHeight (mediaExpandProgress tetap 1.0).
                    child: Transform.scale(
                      scale: mediaRubberScale,
                      alignment: Alignment.topCenter,
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(avatarRadius),
                        child: GestureDetector(
                          onTap: () {
                            if (!hasMedia) return;
                            Navigator.push(context, MediaPreviewRoute(builder: (_) => const ProfileMediaViewerPage()));
                          },
                          child: Hero(
                            tag: 'profile-header-media',
                            flightShuttleBuilder: (flightContext, animation, flightDirection, fromHeroContext, toHeroContext) {
                              return ClipRRect(
                                borderRadius: BorderRadius.zero,
                                child: _ProfileHeaderMediaContent(profile: profile, initial: initial, isTransient: true),
                              );
                            },
                            child: SizedBox.expand(
                              child: _ProfileHeaderMediaContent(profile: profile, initial: initial),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                  if (scrimAlpha > 0)
                    Positioned(
                      top: avatarTop,
                      left: avatarLeft,
                      width: avatarWidth,
                      height: avatarHeight,
                      child: IgnorePointer(
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            borderRadius: BorderRadius.circular(avatarRadius),
                            gradient: LinearGradient(
                              begin: Alignment.topCenter,
                              end: Alignment.bottomCenter,
                              colors: [Colors.transparent, Colors.transparent, Color(scrimAlpha << 24)],
                              stops: const [0.0, 0.5, 1.0],
                            ),
                          ),
                        ),
                      ),
                    ),
                  if (badgeOpacity > 0)
                    Positioned(
                      top: avatarTop,
                      left: avatarLeft,
                      width: avatarWidth,
                      height: avatarHeight,
                      child: Opacity(
                        opacity: badgeOpacity,
                        child: Stack(
                          children: [
                            Positioned(
                              right: -2,
                              bottom: -2,
                              child: GestureDetector(
                                onTap: () => showProfilePhotoOptions(context, ref),
                                child: Container(
                                  padding: const EdgeInsets.all(5),
                                  decoration: BoxDecoration(
                                    color: Theme.of(context).colorScheme.secondary,
                                    shape: BoxShape.circle,
                                    border: Border.all(color: context.cardColor, width: 2),
                                  ),
                                  child: const Icon(Icons.camera_alt_rounded, size: 12, color: Colors.black),
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  if (compactRowOpacity > 0)
                    Positioned(
                      top: topInset + 18.0,
                      left: 20.0 + 68.0 + 14.0,
                      right: 60.0,
                      height: 68.0,
                      child: IgnorePointer(
                        child: Opacity(
                          opacity: compactRowOpacity,
                          child: Column(
                            mainAxisAlignment: MainAxisAlignment.center,
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Row(
                                children: [
                                  Flexible(
                                    child: Text(
                                      profile.name.isNotEmpty ? profile.name : Strings.t(lang, 'view_profile'),
                                      style: TextStyle(fontSize: 17, fontWeight: FontWeight.bold, color: context.textPrimary),
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                  const SizedBox(width: 6),
                                  Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 3),
                                    decoration: BoxDecoration(
                                      color: primary.withOpacity(isDark ? 0.18 : 0.1),
                                      borderRadius: BorderRadius.circular(20),
                                    ),
                                    child: Row(
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        Icon(Icons.workspace_premium_rounded, size: 11, color: primary),
                                        const SizedBox(width: 4),
                                        Text(Strings.t(lang, 'premium_member'), style: TextStyle(fontSize: 10, fontWeight: FontWeight.w800, height: 1.0, color: primary, letterSpacing: 0.2)),
                                      ],
                                    ),
                                  ),
                                ],
                              ),
                              const SizedBox(height: 4),
                              Text(
                                Strings.t(lang, 'manage_account'),
                                style: TextStyle(fontSize: 11.5, color: context.textMuted, fontWeight: FontWeight.w500),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  if (expandedCaptionOpacity > 0)
                    Positioned(
                      top: avatarTop + avatarHeight - 108.0,
