if (await nativeFile.exists()) await nativeFile.delete();
if (await dartFile.exists()) await dartFile.delete();
} catch (_) {}
}

// Membersihkan berkas sementara sisa proses pilih foto/video & trim yang
// tertinggal di cache (mis. sesi yang di-cancel pengguna di tengah jalan,
// atau proses trim yang gagal sebelum sempat menghapus berkas perantaranya
// sendiri). Dipanggil sekali setiap app startup karena tidak ada satupun
// berkas berprefix ini yang seharusnya bertahan lintas sesi aplikasi —
// semuanya perantara murni. Ini juga sekaligus membersihkan cache lama yang
// sudah kadung menumpuk akibat bug sebelumnya (berkas asli hasil pilih
// galeri yang tidak pernah dihapus).
Future<void> _cleanupStaleTempFiles() async {
if (kIsWeb) return;
try {
final dir = await getTemporaryDirectory();
final entities = dir.listSync();
const stalePrefixes = ['picked_profile_', 'trimmed_', 'video_thumb_'];
for (final entity in entities) {
if (entity is! File) continue;
final name = entity.uri.pathSegments.last;
if (stalePrefixes.any((p) => name.startsWith(p))) {
try {
await entity.delete();
} catch (_) {}
}
}
} catch (_) {}
}

// Mengambil frame pertama dari video profil (setelah trim) sebagai
// thumbnail JPEG lewat FFmpeg, lalu di-encode base64 agar bisa langsung
// ditampilkan instan (lihat _ProfileVideoAvatarState) selagi
// VideoPlayerController baru melakukan inisialisasi. Tanpa ini, layar
// akan sempat menampilkan avatar inisial kosong setiap kali membuka tab
// profile sebelum video benar-benar siap diputar.
Future<String?> _extractVideoThumbnailBase64(String videoPath) async {
if (kIsWeb) return null;
try {
final dir = await getTemporaryDirectory();
final outputPath = '${dir.path}/video_thumb_${DateTime.now().microsecondsSinceEpoch}.jpg';
final command = '-y -i "$videoPath" -vframes 1 -q:v 3 '
'-vf "scale=\'min(720,iw)\':-2" "$outputPath"';
final session = await FFmpegKit.execute(command);
final returnCode = await session.getReturnCode();
if (!ReturnCode.isSuccess(returnCode)) return null;
final file = File(outputPath);
if (!await file.exists()) return null;
final bytes = await file.readAsBytes();
try {
await file.delete();
} catch (_) {}
return base64Encode(bytes);
} catch (_) {
return null;
}
}

void main() {
runZonedGuarded(() async {
WidgetsFlutterBinding.ensureInitialized();
unawaited(_cleanupStaleTempFiles());
FlutterError.onError = (FlutterErrorDetails details) {
FlutterError.presentError(details);
_appendDartCrashLog('[Flutter ${DateTime.now()}]\n${details.exceptionAsString()}\n${details.stack}');
};
VisibilityDetectorController.instance.updateInterval = const Duration(milliseconds: 100);
SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
await initializeDateFormatting('id_ID', null);
await LiquidGlassWidgets.initialize();
final prefs = await SharedPreferences.getInstance();
if (!(prefs.getBool('fresh_data_reset_v2') ?? false)) {
await prefs.remove('finance_cards');
await prefs.remove('finance_transactions');
await prefs.remove('user_profile');
await prefs.remove('dummy_data_active');
await prefs.setBool('fresh_data_reset_v2', true);
}
runApp(LiquidGlassWidgets.wrap(
brightnessResolver: Theme.maybeBrightnessOf,
child: ProviderScope(
overrides: [prefsProvider.overrideWithValue(prefs)],
child: const MyFinanceApp(),
),
));
}, (error, stack) {
_appendDartCrashLog('[Zone ${DateTime.now()}]\n$error\n$stack');
});
}

