required this.photoPath,
this.photoBytesBase64,
required this.photoVersion,
this.videoPath,
this.videoVersion = 0,
this.videoCropScale = 1.0,
this.videoCropOffsetX = 0.0,
this.videoCropOffsetY = 0.0,
this.videoThumbnailBytesBase64,
