});

Widget _fallback(Color primary) => CircleAvatar(
radius: radius,
backgroundColor: primary,
child: Text(initial, style: TextStyle(color: Colors.white, fontSize: radius * 0.8, fontWeight: FontWeight.bold)),
);

Widget _photoOrFallback(BuildContext context) {
final primary = Theme.of(context).colorScheme.primary;
final diameter = radius * 2;
final cacheDim = (diameter * MediaQuery.devicePixelRatioOf(context)).round();

if (kIsWeb) {
if (photoBytesBase64 == null) return _fallback(primary);
Uint8List bytes;
try {
bytes = base64Decode(photoBytesBase64!);
} catch (_) {
return _fallback(primary);
}
return ClipOval(
key: ValueKey('avatar-web-$photoVersion'),
child: Image.memory(
bytes,
width: diameter,
height: diameter,
fit: BoxFit.cover,
cacheWidth: cacheDim,
cacheHeight: cacheDim,
gaplessPlayback: true,
errorBuilder: (context, error, stackTrace) => _fallback(primary),
),
);
}

if (photoPath == null) return _fallback(primary);
return ClipOval(
key: ValueKey('avatar-$photoVersion'),
child: Image.file(
File(photoPath!),
width: diameter,
height: diameter,
fit: BoxFit.cover,
cacheWidth: cacheDim,
cacheHeight: cacheDim,
errorBuilder: (context, error, stackTrace) => _fallback(primary),
),
);
}

@override
Widget build(BuildContext context) {
final diameter = radius * 2;
if (!kIsWeb && videoPath != null) {
return ClipOval(
key: ValueKey('avatar-video-$videoVersion'),
child: SizedBox(
width: diameter,
height: diameter,
child: _ProfileVideoAvatar(
videoPath: videoPath!,
version: videoVersion,
diameter: diameter,
scale: videoCropScale,
offsetX: videoCropOffsetX,
offsetY: videoCropOffsetY,
fallback: _photoOrFallback(context),
thumbnailBytesBase64: videoThumbnailBytesBase64,
),
),
);
}
return _photoOrFallback(context);
}
}

class ProfileVideoManager {
static VideoPlayerController? controller;
static String? currentPath;
static int? currentVersion;
static int refCount = 0;
static bool isPreviewActive = false;

static Future<VideoPlayerController?> acquire(String path, {int version = 0}) async {
if (currentPath == path && currentVersion == version && controller != null) {
refCount++;
return controller;
}

if (controller != null) {
await controller!.dispose();
controller = null;
}

final file = File(path);
if (!file.existsSync()) return null;

// mixWithOthers: true mencegah video ini merebut audio focus dari
// sistem. Tanpa ini, video_player di Android tetap meminta audio
// focus begitu play() dipanggil walau volume di-set 0 (senyap) —
// itulah yang memaksa musik dari aplikasi lain (Spotify dll) pause
// setiap kali avatar/preview video profil ini diputar.
final newController = VideoPlayerController.file(
file,
videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
);
try {
await newController.initialize();
await newController.setLooping(true);
await newController.setVolume(0);
newController.play();
controller = newController;
currentPath = path;
currentVersion = version;
refCount = 1;
return controller;
} catch (_) {
newController.dispose();
return null;
}
}

static void release() {
if (refCount > 0) {
refCount--;
if (refCount == 0) {
controller?.dispose();
controller = null;
currentPath = null;
currentVersion = null;
}
}
}
}

class _ProfileVideoAvatar extends StatefulWidget {
final String videoPath;
final int version;
final double diameter;
final double scale;
final double offsetX;
final double offsetY;
final Widget fallback;
final String? thumbnailBytesBase64;
// Dipakai HANYA untuk widget sementara yang dirender oleh Hero
// flightShuttleBuilder selama animasi transisi (~380ms). Widget ini TIDAK
// boleh ikut serta dalam ref-counting ProfileVideoManager maupun mengubah
// status play/pause controller yang dipakai bersama header & preview,
// karena VisibilityDetector-nya bisa sempat melaporkan visibleFraction
// rendah saat posisinya berpindah/di-clip di tengah animasi flight —
// itulah yang sebelumnya membuat video controller utama ikut ter-pause
// dan tidak melanjutkan setelah keluar dari preview full.
final bool isTransient;
const _ProfileVideoAvatar({
required this.videoPath,
this.version = 0,
required this.diameter,
required this.scale,
required this.offsetX,
required this.offsetY,
required this.fallback,
this.thumbnailBytesBase64,
this.isTransient = false,
});

@override
State<_ProfileVideoAvatar> createState() => _ProfileVideoAvatarState();
}

class _ProfileVideoAvatarState extends State<_ProfileVideoAvatar> {
VideoPlayerController? _controller;
bool _failed = false;
bool _isVisible = true;
late final Key _visibilityKey = UniqueKey();

@override
void initState() {
super.initState();
_setup();
}

@override
void didUpdateWidget(covariant _ProfileVideoAvatar oldWidget) {
super.didUpdateWidget(oldWidget);
if (widget.isTransient) return;
// Nama berkas video profil selalu sama (profile_video.mp4), jadi
// perbandingan path saja tidak cukup mendeteksi video baru yang baru
// menimpa berkas lama. videoVersion dipakai sebagai penanda eksplisit
// agar controller lama dilepas & video baru langsung dimuat tanpa perlu
// pindah tab untuk memicu rebuild.
if (oldWidget.videoPath != widget.videoPath || oldWidget.version != widget.version) {
ProfileVideoManager.release();
_controller = null;
_failed = false;
_setup();
}
}

Future<void> _setup() async {
if (widget.isTransient) {
// Hanya "mengintip" controller yang sudah aktif tanpa ikut
// acquire/release, supaya tidak mengganggu ref-count controller asli
// yang sedang dipakai header/preview.
final c = ProfileVideoManager.controller;
final matches = c != null &&
ProfileVideoManager.currentPath == widget.videoPath &&
ProfileVideoManager.currentVersion == widget.version &&
c.value.isInitialized;
if (!mounted) return;
if (matches) {
setState(() => _controller = c);
} else {
setState(() => _failed = true);
}
return;
}
final c = await ProfileVideoManager.acquire(widget.videoPath, version: widget.version);
if (!mounted) {
ProfileVideoManager.release();
return;
}
if (c == null) {
setState(() => _failed = true);
} else {
setState(() => _controller = c);
}
}

void _handleVisibility(VisibilityInfo info) {
// Widget transient (Hero flightShuttleBuilder) tidak boleh pernah
// memanggil play()/pause() pada controller bersama: perubahan
// visibleFraction selama animasi flight bukan sinyal yang valid untuk
// menentukan status pemutaran video header/preview yang sebenarnya.
if (widget.isTransient) return;
final controller = _controller;
if (controller == null || !controller.value.isInitialized) return;
final visible = info.visibleFraction > 0.04;
if (visible == _isVisible) return;
_isVisible = visible;
if (visible || ProfileVideoManager.isPreviewActive) {
controller.play();
} else {
controller.pause();
}
}

@override
void dispose() {
if (!widget.isTransient) {
ProfileVideoManager.release();
}
super.dispose();
}

@override
Widget build(BuildContext context) {
final controller = _controller;
if (_failed) {
return widget.fallback;
}
if (controller == null || !controller.value.isInitialized) {
// While the real VideoPlayerController is still initializing, show the
// captured first-frame thumbnail (if any) instead of flashing the
// plain initial-letter placeholder.
final thumbBase64 = widget.thumbnailBytesBase64;
if (thumbBase64 != null) {
try {
final thumbBytes = base64Decode(thumbBase64);
return Image.memory(
thumbBytes,
width: double.infinity,
height: double.infinity,
fit: BoxFit.cover,
gaplessPlayback: true,
errorBuilder: (context, error, stackTrace) => widget.fallback,
);
} catch (_) {
return widget.fallback;
}
}
return widget.fallback;
}
// Offset/scale crop video ini awalnya dikalibrasi terhadap preview crop
// PERSEGI 280x280 (lihat _VideoCropPageState), lalu dipakai ulang di sini
// untuk kotak avatar/header yang ukuran & rasio aspeknya berbeda (header
// profil penuh lebar & tidak persegi). Tanpa margin ekstra ini, translate
// (pergeseran posisi) bisa mendorong konten yang sudah di-cover keluar
// dari batas kotak, memunculkan celah/ruang kosong (putih) di salah satu
// sisi (mis. atas & kanan) karena BoxFit.cover jadi tidak lagi menutupi
// seluruh area setelah digeser. safeScale memastikan skala selalu cukup
// besar untuk mengompensasi jarak pergeseran tersebut.
final double safeScale = max(
widget.scale,
1.0 + 2.0 * (widget.offsetX.abs() + widget.offsetY.abs()),
);
return RepaintBoundary(
child: VisibilityDetector(
key: _visibilityKey,
onVisibilityChanged: _handleVisibility,
child: ClipRect(
child: Transform.translate(
offset: Offset(widget.offsetX * widget.diameter, widget.offsetY * widget.diameter),
child: Transform.scale(
scale: safeScale,
child: FittedBox(
fit: BoxFit.cover,
child: SizedBox(
width: controller.value.size.width,
height: controller.value.size.height,
child: VideoPlayer(controller),
),
),
),
),
),
),
);
}
}

