class _HeaderSnapScrollPhysics extends ScrollPhysics {
final double boundary;
final bool Function() isLocked;
final bool Function() hasMedia;
final bool Function() allowPreviewEntry;
final double maxTopRubberOffset;

const _HeaderSnapScrollPhysics({
required this.boundary,
required this.isLocked,
required this.hasMedia,
required this.allowPreviewEntry,
this.maxTopRubberOffset = 70.0,
super.parent,
});

@override
_HeaderSnapScrollPhysics applyTo(ScrollPhysics? ancestor) {
return _HeaderSnapScrollPhysics(
boundary: boundary,
isLocked: isLocked,
hasMedia: hasMedia,
allowPreviewEntry: allowPreviewEntry,
maxTopRubberOffset: maxTopRubberOffset,
parent: buildParent(ancestor),
);
}

@override
double applyBoundaryConditions(ScrollMetrics position, double value) {
// Catatan: clamp "gesture crossing lock" yang sebelumnya ada di sini
// (menahan pixels tepat di `boundary` selama drag yang dimulai dari
// area expanded) sengaja dihapus. Flag isLocked() (_gestureCrossingLocked)
// di-reset ke false oleh ScrollEndNotification SEBELUM ballistic/spring
// simulation sempat berjalan, sehingga clamp ini tidak pernah benar-benar
// melindungi animasi snap dari overshoot — efek nyatanya hanya mengunci
// drag jari yang MASIH berlangsung begitu offset menyentuh `boundary`,
// membuat scroll ke konten sheet di bawahnya terasa tertahan padahal
// masih ada ruang, sampai jari dilepas dan gesture baru dimulai.
// Menghapus clamp ini membuat drag tunggal yang meng-collapse header lalu
// lanjut men-scroll konten sheet terasa menyatu/mulus tanpa perlu
// melepas jari terlebih dahulu.

// FASE 2 (EXPANDED + RUBBER): gesture PERTAMA yang diteruskan melewati
// batas full-expand (offset 0) TIDAK boleh menembus ke FASE 3 (full
// preview) — lihat allowPreviewEntry & _handleScrollNotification. Alih-
// alih di-freeze keras di 0, beri sedikit ruang overscroll elastis
// (rubber) hingga maxTopRubberOffset; resistance-nya sendiri diberikan
// lewat applyPhysicsToUserOffset di bawah, mirip pola overscroll bawah.
if (value <= 0.0) {
if (!allowPreviewEntry()) {
final double minPos = -maxTopRubberOffset;
if (value < minPos && position.pixels >= minPos) {
return value - minPos;
}
if (minPos > position.pixels && position.pixels > value) {
return value - position.pixels;
}
}
// PENTING: setelah batas keras rubber di atas, offset negatif (baik
// untuk rubber Fase 2 maupun full preview Fase 3) HARUS selalu
// dibiarkan bebas (return 0.0 = tanpa correction) di sini, alih-alih
// jatuh ke `super`/physics parent (ClampingScrollPhysics). Clamping
// akan langsung mengunci pixels di 0 begitu value negatif, yang
// mematikan efek scale gambar/video Fase 2 (mediaRubberProgress
// selalu 0) sekaligus mematikan gesture full preview Fase 3.
return 0.0;
}

// Batas bawah DIKUNCI KERAS (tanpa efek rubber/pantul sama sekali) —
// berbeda dari batas atas Fase 2 yang sengaja tetap elastis.
final maxPos = position.maxScrollExtent;
if (maxPos <= position.pixels && position.pixels < value) {
return value - maxPos;
}
if (position.pixels < maxPos && maxPos < value) {
return value - maxPos;
}

return super.applyBoundaryConditions(position, value);
}

@override
double applyPhysicsToUserOffset(ScrollMetrics position, double offset) {
// FASE 2 rubber: resistance overscroll atas, semakin dalam ditarik
// semakin besar hambatannya (mendekati maxTopRubberOffset). Batas
// bawah tidak lagi punya efek rubber sama sekali (lihat
// applyBoundaryConditions yang mengunci keras di maxScrollExtent).
if (position.pixels < 0.0 && !allowPreviewEntry()) {
final overscroll = -position.pixels;
final fraction = (overscroll / maxTopRubberOffset).clamp(0.0, 1.0);
final friction = 1.0 - (fraction * fraction);
return super.applyPhysicsToUserOffset(position, offset) * friction;
}
return super.applyPhysicsToUserOffset(position, offset);
}

@override
Simulation? createBallisticSimulation(ScrollMetrics position, double velocity) {
// 1. Pull down to preview snap (HANYA untuk gesture yang diizinkan masuk
// FASE 3 / full preview; selain itu selalu kembali ke EXPANDED (0.0) —
// termasuk saat melepas jari di tengah rubber effect FASE 2).
if (position.pixels < 0.0) {
if (allowPreviewEntry() && hasMedia() && (position.pixels <= -50.0 || (velocity < -500.0 && position.pixels < -15.0))) {
return ScrollSpringSimulation(
spring,
position.pixels,
-100.0,
velocity,
tolerance: toleranceFor(position),
);
} else {
return ScrollSpringSimulation(
spring,
position.pixels,
0.0,
velocity,
tolerance: toleranceFor(position),
);
}
}

// 2. Snap inside expansion area
if (position.pixels > 0 && position.pixels < boundary) {
if (velocity < -300.0) {
return ScrollSpringSimulation(spring, position.pixels, 0.0, velocity, tolerance: toleranceFor(position));
} else if (velocity > 300.0) {
return ScrollSpringSimulation(spring, position.pixels, boundary, velocity, tolerance: toleranceFor(position));
}

final target = position.pixels > (boundary * 0.45) ? boundary : 0.0;
return ScrollSpringSimulation(
spring,
position.pixels,
target,
velocity,
tolerance: toleranceFor(position),
);
}

return super.createBallisticSimulation(position, velocity);
}
}

class ProfilePage extends ConsumerStatefulWidget {
const ProfilePage({super.key});
@override
ConsumerState<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends ConsumerState<ProfilePage> {
late final ScrollController _scrollController;
bool _initialized = false;
double _scrollOffset = 0.0;
double _maxExpandScroll = 0.0;
bool _gestureCrossingLocked = false;
bool _gestureAllowsPreviewEntry = true;
bool _previewPushed = false;

// FASE 2 — EXPANDED + RUBBER EFFECT: state & batasan terpisah dari
// mediaExpandProgress/previewProgress. Rubber tidak pernah mengubah
// expanded state maupun membuka FULL PREVIEW; hanya feedback fisik
// sementara yang kembali ke 0 saat gesture dilepas (lihat
// _HeaderSnapScrollPhysics.createBallisticSimulation).
static const double _rubberMaxRawOffset = 95.0;
static const double _mediaRubberMaxExtraScale = 0.22;

@override
void didChangeDependencies() {
super.didChangeDependencies();
if (!_initialized) {
final topInset = MediaQuery.paddingOf(context).top;
// Posisi di mana Sheet akan berada ketika compact
final compactHeight = topInset + 18.0 + 68.0 + 16.0;
// Posisi awal Sheet (ruang kosong transparent) ketika di-expand, dikurangi overlap 20px
final expandedSheetTop = 380.0 - 20.0;

_maxExpandScroll = expandedSheetTop - compactHeight;

_scrollController = ScrollController(initialScrollOffset: _maxExpandScroll);
_scrollOffset = _maxExpandScroll;

_scrollController.addListener(() {
if (!mounted) return;

final newOffset = _scrollController.offset;
setState(() {
_scrollOffset = newOffset;
});

// previewProgress (scrim & opacity bottom nav) HANYA berlaku untuk
// FASE 3 (gesture kedua yang diizinkan masuk preview). Offset
// negatif dari FASE 2 (rubber) tidak boleh ikut memicu ini.
final progress = (newOffset < 0 && _gestureAllowsPreviewEntry) ? (-newOffset / 100.0).clamp(0.0, 1.0) : 0.0;
Future.microtask(() {
if (mounted) {
ref.read(profilePreviewProgressProvider.notifier).state = progress;
}
});

if (_scrollOffset <= -98.0 && !_previewPushed && _gestureAllowsPreviewEntry) {
final profile = ref.read(userProfileProvider);
if (profile.hasPhoto || profile.hasVideo) {
_previewPushed = true;
Navigator.push(context, MediaPreviewRoute(builder: (_) => const ProfileMediaViewerPage())).then((_) {
_previewPushed = false;
if (mounted && _scrollController.hasClients) {
_scrollController.jumpTo(0.0);
}
// Jaga-jaga: pastikan video header kembali melanjutkan
// pemutaran (bukan freeze/pause) setelah preview fullscreen
// ditutup, tanpa harus pindah tab dulu.
final headerController = ProfileVideoManager.controller;
if (headerController != null && headerController.value.isInitialized && !headerController.value.isPlaying) {
headerController.play();
}
});
}
}
});

_initialized = true;
}
}

@override
void dispose() {
_scrollController.dispose();
Future.microtask(() {
try {
ref.read(profilePreviewProgressProvider.notifier).state = 0.0;
} catch (_) {}
});
super.dispose();
}

void _collapseMediaNow() {
if (_scrollController.hasClients) {
_scrollController.animateTo(
_maxExpandScroll,
duration: const Duration(milliseconds: 400),
curve: Curves.easeOutCubic,
);
}
}

bool _handleScrollNotification(ScrollNotification notification) {
if (notification is ScrollStartNotification) {
final currentOffset = _scrollController.hasClients ? _scrollController.offset : _maxExpandScroll;
final startedBelowDefault = currentOffset < _maxExpandScroll - 0.5;
final isRealDrag = notification.dragDetails != null;
_gestureCrossingLocked = isRealDrag && startedBelowDefault;
// Gesture (drag) baru hanya diizinkan masuk ke area preview (offset
// negatif) jika dimulai saat header SUDAH berada di/lewat batas full
// expand (offset <= 0). Jika dimulai dari posisi masih positif
// (compact/setengah expand), gesture ini dikunci di batas 0 dan tidak
// bisa menembus ke preview sampai jari dilepas & discroll ulang.
if (isRealDrag) {
_gestureAllowsPreviewEntry = currentOffset <= 0.5;
}
} else if (notification is ScrollEndNotification) {
_gestureCrossingLocked = false;
}
return false;
}

@override
Widget build(BuildContext context) {
final lang = ref.watch(langProvider);
final profile = ref.watch(userProfileProvider);
final initial = profile.name.isNotEmpty ? profile.name.substring(0, 1).toUpperCase() : '?';
final hasMedia = profile.hasPhoto || profile.hasVideo;
final topInset = MediaQuery.paddingOf(context).top;
final screenWidth = MediaQuery.sizeOf(context).width;

double t = 1.0;
double parallaxOffset = 0.0;
double previewProgress = 0.0;
double mediaRubberProgress = 0.0;
// Seberapa besar konten sheet perlu digeser ke ATAS lewat
// Transform.translate (BUKAN lagi memangkas tinggi spacer) agar posisi
// sheet tetap terpaku di viewport yang sama walau scroll offset sedang
// negatif (overscroll rubber Fase 2).
// PENTING: nilai ini TIDAK PERNAH dipakai untuk mengubah ukuran/tinggi
// widget apa pun di dalam CustomScrollView. Mengubah ukuran LAYOUT
// berdasarkan _scrollOffset (cara lama) memicu
// BallisticScrollActivity.applyNewDimensions() yang me-restart simulasi
// ballistic setiap frame selama animasi snap — inilah penyebab bug
// scroll "jalan sendiri" (naik-turun tanpa disentuh) di tab profile.
// Transform hanya mengubah posisi gambar (paint), jadi aman dari bug ini.
double sheetSpacerCompensation = 0.0;

if (_scrollOffset > _maxExpandScroll) {
t = 0.0;
parallaxOffset = (_scrollOffset - _maxExpandScroll) * 1.0;
} else if (_scrollOffset >= 0) {
t = 1.0 - (_scrollOffset / _maxExpandScroll);
parallaxOffset = 0.0;
} else if (_gestureAllowsPreviewEntry) {
// FASE 3 — FULL PREVIEW (hanya dari gesture kedua)
t = 1.0;
parallaxOffset = 0.0;
previewProgress = (-_scrollOffset / 100.0).clamp(0.0, 1.0);
} else {
// FASE 2 — EXPANDED + RUBBER EFFECT (gesture pertama diteruskan).
// mediaExpandProgress (t) TETAP 1.0, rubber disimpan terpisah dan
// tidak pernah membuka FULL PREVIEW.
t = 1.0;
parallaxOffset = 0.0;
final double rawRubberProgress = (-_scrollOffset / _rubberMaxRawOffset).clamp(0.0, 1.0);
mediaRubberProgress = rawRubberProgress;
// Pangkas spacer sebesar overscroll (-_scrollOffset, positif) supaya
// posisi konten sheet (yang dimulai tepat setelah spacer) tetap di
// viewport-y yang sama persis seperti saat scrollOffset 0 — sheet
// jadi terpaku, tidak ikut turun & tidak lepas dari overlap media.
sheetSpacerCompensation = -_scrollOffset;
}

final double screenHeight = MediaQuery.sizeOf(context).height;

double avatarWidth;
double avatarHeight;
double avatarRadius;
double avatarTop;
double avatarLeft;

if (previewProgress > 0.0) {
final targetHeight = screenWidth;
final targetTop = (screenHeight - targetHeight) / 2;

avatarWidth = screenWidth;
avatarHeight = lerpDouble(380.0, targetHeight, previewProgress)!;
avatarTop = lerpDouble(0.0, targetTop, previewProgress)!;
avatarLeft = 0.0;
avatarRadius = 0.0;
} else {
avatarWidth = lerpDouble(68.0, screenWidth, t)!;
avatarHeight = lerpDouble(68.0, 380.0, t)!;
avatarRadius = lerpDouble(34.0, 0, t)!;
avatarTop = lerpDouble(topInset + 18.0, 0.0, t)!;
avatarLeft = lerpDouble(20.0, 0.0, t)!;
}

final double compactRowOpacity = (1 - t * 2.6).clamp(0.0, 1.0);
final double expandedCaptionOpacity = (((t - 0.45) / 0.55).clamp(0.0, 1.0)) * (1.0 - previewProgress);
final double badgeOpacity = (1 - t * 5).clamp(0.0, 1.0);
final double chevronOpacity = (((t - 0.5) / 0.5).clamp(0.0, 1.0)) * (1.0 - previewProgress);
final int scrimAlpha = (0x99 * t * (1.0 - previewProgress)).round();
final double sheetOpacity = 1.0 - previewProgress;
// FASE 2 rubber: scale media & offset sheet berasal dari
// mediaRubberProgress / sheetRubberProgress (lihat blok if/else di
// atas), bukan dari t atau previewProgress.
final double mediaRubberScale = 1.0 + mediaRubberProgress * _mediaRubberMaxExtraScale;
// Efek rubber pada sheet: regangan skala kecil (bukan translate) yang
// di-anchor dari sisi atas, jadi sheet tetap menempel/overlap dengan
// media persis di titik yang sama, hanya meregang tipis ke bawah —
