class ProfileMediaViewerPage extends ConsumerStatefulWidget {
const ProfileMediaViewerPage({super.key});
@override
ConsumerState<ProfileMediaViewerPage> createState() => _ProfileMediaViewerPageState();
}

class _ProfileMediaViewerPageState extends ConsumerState<ProfileMediaViewerPage> {
VideoPlayerController? _controller;
bool _muted = false;
bool _controlsVisible = true;
double _dragOffset = 0;
bool _videoFailed = false;

@override
void initState() {
super.initState();
ProfileVideoManager.isPreviewActive = true;
final profile = ref.read(userProfileProvider);
if (!kIsWeb && profile.videoPath != null) {
_setupVideo(profile.videoPath!, profile.videoVersion);
}
}

Future<void> _setupVideo(String path, int version) async {
final c = await ProfileVideoManager.acquire(path, version: version);
if (!mounted) {
ProfileVideoManager.release();
return;
}
if (c == null) {
setState(() => _videoFailed = true);
} else {
c.setVolume(_muted ? 0 : 1);
c.play();
setState(() => _controller = c);
}
}

void _toggleMute() {
setState(() => _muted = !_muted);
_controller?.setVolume(_muted ? 0 : 1);
}

@override
void dispose() {
ProfileVideoManager.isPreviewActive = false;
final previewController = _controller;
if (previewController != null && previewController.value.isInitialized) {
previewController.setVolume(0);
// Preview sempat menaikkan volume & memutar ulang controller; pastikan
// playback tetap berjalan (tidak ter-pause) ketika kembali ke
// avatar/header kecil, supaya video tidak "membeku" dan tidak perlu
// pindah tab untuk melanjutkan.
if (!previewController.value.isPlaying) {
previewController.play();
}
}
ProfileVideoManager.release();
super.dispose();
}

Widget _staticFallback(UserProfile profile) {
final width = MediaQuery.sizeOf(context).width;
Widget child;
if (kIsWeb && profile.photoBytesBase64 != null) {
try {
child = Image.memory(base64Decode(profile.photoBytesBase64!), fit: BoxFit.contain, gaplessPlayback: true);
} catch (_) {
child = _textFallback(profile, width);
}
} else if (profile.photoPath != null) {
child = Image.file(File(profile.photoPath!), fit: BoxFit.contain, gaplessPlayback: true);
} else if (profile.videoPath != null && profile.videoThumbnailBytesBase64 != null) {
try {
child = Image.memory(base64Decode(profile.videoThumbnailBytesBase64!), fit: BoxFit.contain, gaplessPlayback: true);
} catch (_) {
child = _textFallback(profile, width);
}
} else {
child = _textFallback(profile, width);
}

return InteractiveViewer(
maxScale: 4,
child: child,
);
}

Widget _textFallback(UserProfile profile, double width) {
return Container(
color: Theme.of(context).colorScheme.primary,
alignment: Alignment.center,
child: Text(
profile.name.isNotEmpty ? profile.name.substring(0, 1).toUpperCase() : '?',
style: TextStyle(color: Colors.white, fontSize: width * 0.26, fontWeight: FontWeight.bold),
),
);
}

@override
Widget build(BuildContext context) {
final profile = ref.watch(userProfileProvider);
final isVideo = !kIsWeb && profile.videoPath != null;
final dismissProgress = (_dragOffset / 400).clamp(0.0, 1.0);

return AnnotatedRegion<SystemUiOverlayStyle>(
value: const SystemUiOverlayStyle(
statusBarColor: Colors.transparent,
statusBarIconBrightness: Brightness.light,
statusBarBrightness: Brightness.dark,
),
child: GestureDetector(
onVerticalDragUpdate: (details) {
setState(() => _dragOffset = (_dragOffset + details.delta.dy).clamp(0, 500));
},
onVerticalDragEnd: (details) {
final velocity = details.primaryVelocity ?? 0;
if (_dragOffset > 130 || velocity > 800) {
Navigator.pop(context);
} else {
setState(() => _dragOffset = 0);
}
},
onTap: () => setState(() => _controlsVisible = !_controlsVisible),
child: Scaffold(
backgroundColor: Colors.black.withOpacity(1 - dismissProgress * 0.7),
body: Stack(
children: [
Center(
child: Transform.translate(
offset: Offset(0, _dragOffset),
child: Hero(
tag: 'profile-header-media',
child: AspectRatio(
aspectRatio: 1,
child: isVideo && !_videoFailed
? (_controller != null && _controller!.value.isInitialized
? ClipRect(
child: InteractiveViewer(
maxScale: 4,
child: Transform.translate(
offset: Offset(profile.videoCropOffsetX * MediaQuery.sizeOf(context).width, profile.videoCropOffsetY * MediaQuery.sizeOf(context).width),
child: Transform.scale(
scale: max(profile.videoCropScale, 1.0 + 2.0 * (profile.videoCropOffsetX.abs() + profile.videoCropOffsetY.abs())),
child: FittedBox(
fit: BoxFit.cover,
child: SizedBox(
width: _controller!.value.size.width,
height: _controller!.value.size.height,
child: VideoPlayer(_controller!),
),
),
),
),
),
)
: _staticFallback(profile))
: _staticFallback(profile),
),
),
),
),
AnimatedOpacity(
opacity: _controlsVisible ? 1 : 0,
duration: const Duration(milliseconds: 180),
child: SafeArea(
child: Padding(
padding: const EdgeInsets.all(12),
child: Row(
mainAxisAlignment: MainAxisAlignment.spaceBetween,
children: [
_HeaderIconButton(icon: Icons.close_rounded, onTap: () => Navigator.pop(context)),
if (isVideo && !_videoFailed)
_HeaderIconButton(
icon: _muted ? Icons.volume_off_rounded : Icons.volume_up_rounded,
onTap: _toggleMute,
),
],
),
),
),
),
],
),
),
));
}
}

