        // opaque dipakai supaya tap di RUANG KOSONG (bukan tombol/input)
        // ikut terdeteksi, tanpa memblokir tap pada widget anak (tombol,
        // TextField, dsb.) yang tetap diproses seperti biasa.
        body: GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => FocusScope.of(context).unfocus(),
          child: Stack(
          children: [
            Positioned.fill(
              child: IgnorePointer(
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                      colors: [
                        bg.withOpacity(0.0),
                        primary.withOpacity(isDark ? 0.16 : 0.10),
                      ],
                      stops: const [0.0, 1.0],
                    ),
                  ),
                ),
              ),
            ),
            SafeArea(
              top: false,
              child: LayoutBuilder(
                builder: (context, viewportConstraints) {
                  // Jarak atas diperbesar (dari 78 sebelumnya) supaya ada
                  // ruang napas yang cukup antara judul "Pindai Struk" di
                  // header dan panel gambar/form struk di bawahnya —
                  // sebelumnya keduanya terlalu berdempetan pada posisi awal.
                  const topPad = 108.0;
                  // Dikurangi dari 116 — ruang kosong di bawah daftar
                  // belanja terdeteksi sebelum mentok batas scroll terasu
                  // terlalu jauh; 88 masih cukup menghindari konten
                  // tertutup tombol "Simpan" (FAB) tanpa sisa jarak
                  // kosong berlebih.
                  final bottomPad = hasResult ? 88.0 : 24.0;
                  return SingleChildScrollView(
                    controller: _scrollController,
                    physics: const BouncingScrollPhysics(),
                    padding: EdgeInsets.fromLTRB(20, topPad, 20, bottomPad),
                    child: ConstrainedBox(
                      constraints: BoxConstraints(
                        minHeight: (viewportConstraints.maxHeight - topPad - bottomPad).clamp(0, double.infinity),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisAlignment: hasResult ? MainAxisAlignment.start : MainAxisAlignment.center,
                        mainAxisSize: MainAxisSize.max,
                        children: [
                          AnimatedSwitcher(
                            duration: const Duration(milliseconds: 340),
                            switchInCurve: Curves.easeOutCubic,
                            switchOutCurve: Curves.easeInCubic,
                            transitionBuilder: (child, animation) => FadeTransition(
                              opacity: animation,
                              child: SlideTransition(
                                position: Tween<Offset>(begin: const Offset(0, 0.04), end: Offset.zero).animate(animation),
                                child: child,
                              ),
                            ),
                            child: _imageFile == null
                                ? (_autoStarting
                                    ? const SizedBox.shrink(key: ValueKey('autostarting'))
                                    : _buildEmptyState(context, key: const ValueKey('empty')))
                                : _buildPreview(context, key: ValueKey('preview_${_imageFile!.path}')),
                          ),
                          AnimatedSize(
                            duration: const Duration(milliseconds: 320),
                            curve: Curves.easeOutCubic,
                            alignment: Alignment.topCenter,
                            child: _scanning
                                ? _buildScanningState(context)
                                : (hasResult ? _buildResultForm(context) : const SizedBox(width: double.infinity)),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
            Positioned(
              top: 0,
              left: 0,
              right: 0,
              child: SafeArea(
                bottom: false,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(20, 16, 20, 12),
                  child: Row(children: [
                    GestureDetector(
                      onTap: () => Navigator.pop(context),
                      child: LiquidGlass(
                        borderRadius: 999,
                        tint: isDark ? Colors.black : null,
                        intensity: isDark ? 1.6 : 1.0,
                        borderColor: isDark ? context.borderColor : null,
                        child: Padding(
                          padding: const EdgeInsets.all(10),
                          child: Icon(SolarIconsOutline.arrowLeft, size: 20, color: context.textPrimary),
                        ),
                      ),
                    ),
                    const SizedBox(width: 16),
                    ScrollFadeTitle(controller: _scrollController, child: Text(Strings.t(lang, 'scan_receipt'), style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: context.textPrimary))),
                  ]),
                ),
              ),
            ),
          ],
          ),
        ),
        floatingActionButton: AnimatedScale(
          duration: const Duration(milliseconds: 260),
          curve: Curves.easeOutBack,
          scale: hasResult ? 1.0 : 0.0,
          child: AnimatedOpacity(
            duration: const Duration(milliseconds: 200),
            opacity: hasResult ? 1.0 : 0.0,
            child: IgnorePointer(
              ignoring: !hasResult,
              child: FloatingActionButton.extended(
                onPressed: _save,
                icon: const Icon(Icons.check_rounded),
                label: Text(Strings.t(lang, 'save')),
              ),
            ),
          ),
        ),
      ),
    );
  }

