      return;
    }
    setState(() {
      _testing = true;
      _testSuccess = null;
      _testMessage = null;
    });
    final result = await ReceiptScannerService().testApiKeys(
      keys,
      provider: provider,
      model: model,
    );
    if (!mounted) return;
    setState(() {
      _testing = false;
      _testSuccess = result.success;
      _testMessage = result.message;
    });
  }

